export const COMPENDIUM_REALITE_V9_CRAWLERS_PNJ_DOCX = [{"id":"pnj-crawlers-docx-veronica-silver","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Veronica SILVER","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Transversal"],"pnj":{"completeness":"detailed","real_name":"Veronica SILVER","identity_keys":["Veronica SILVER","Reine des Crawlers, l’Arbitre"],"statut":"Tous les Crawlers, mafias, police, armée,…","organisation":"Crawlers","age":"34 ans","nationalite":"Americaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Veronica SILVER"],["Alias / désignation","Reine des Crawlers, l’Arbitre"],["Âge","34 ans"],["Affiliations","Tous les Crawlers, mafias, police, armée,…"],["Nationalité d’origine","Americaine"],["Famille Crawler","Crawlers"],["Sous-type","Transversal"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Henry EDWARDS"],["Fuyumi SHINODA"],["Et bien d’autres…"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Bien qu’elle soit rangée au sein des « détectives et informateurs », parce qu’elle est officiellement"},{"type":"p","text":"détective privée, « LA SILVER » est la crawler la plus polyvalente et incarnant au mieux l’esprit"},{"type":"p","text":"général de cette faction. C’est aussi la plus respectée en tant que Crawler au point d’être surnommée"},{"type":"p","text":"« l’Arbitre », puisqu’elle s’assoit à la table du conseil des mafias pour arbitrer les échanges quand il le"},{"type":"p","text":"faut."},{"type":"p","text":"Dans son quotidien, c’est une détective qui ne semble pourtant pas vivre dans le luxe."},{"type":"p","text":"Veronica Silver est une ancienne militaire de l’Army ayant brillé pendant la guerre contre la Corée du"},{"type":"p","text":"Nord, génie autodestructeur à la jeunesse ravagée, elle a réussi à s’épanouir dans ce monde"},{"type":"p","text":"déconstruit, précisément parce qu’elle était encore plus chaotique que ce monde."},{"type":"p","text":"Il existe peu de génies de son niveau, c’est pourquoi, malgré son physique extraordinaire, ses"},{"type":"p","text":"capacités de combat, de tir mais aussi son réseau démentiel, elle est plus encore admirée par sa"},{"type":"p","text":"perspicacité et sa logique, hélas trop intelligente pour une société aussi artificielle, elle souffre d’un"},{"type":"p","text":"cynisme démesuré."},{"type":"p","text":"détective est clairement la personne à le moins sous-estimer au sein des Crawlers puisqu’elle compte"},{"type":"p","text":"au sein des « TEN », les dix personnes les plus influentes de TUC, tout simplement."},{"type":"p","text":"En tant que détective, Veronica s’occupe de pratiquement n’importe quel genre d’affaires, en vérité"},{"type":"p","text":"le critère principal ne sera jamais l’argent, ce sera l’intérêt, en revanche, il est presque impossible de"},{"type":"p","text":"déterminer si elle sera intéressée ou non tant elle est imprévisible."},{"type":"p","text":"compliquées. Elle aurait une proximité plus grande avec les yakuzas du côté des mafias mais ne les a"},{"type":"p","text":"jamais favorisés d’aucune façon."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"On ignore ses augmentations et certains disent qu’elle n’en aurait simplement aucune, mais ce"},{"type":"p","text":"Son génie est tel que le LAUS (police de Los Angeles) l’emploie officieusement sur les affaires les plus"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-ryan-isaiah-burton","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ryan Isaiah BURTON","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers"],"pnj":{"completeness":"detailed","real_name":"Ryan Isaiah BURTON","identity_keys":["Ryan Isaiah BURTON","White man"],"statut":"fixers","organisation":"Fixers","age":"46 ans","nationalite":"Americaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ryan Isaiah BURTON"],["Alias / désignation","White man"],["Âge","46 ans"],["Affiliations","fixers"],["Nationalité d’origine","Americaine"],["Famille Crawler","Fixers"],["Sous-type","Fixers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Arkhangel"],["Il Papa"],["Typhon sanglant"],["Et d’autres…"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Surnommé « Whiteman », il tient la « Blanchisserie », un vaste complexe semi-souterrains et un"},{"type":"p","text":"réseau de laverie à travers toute la Californie et le Mexique."},{"type":"p","text":"La blanchisserie existe depuis les années 1970, elle servait essentiellement aux nettoyeurs, véritable"},{"type":"p","text":"blanchisserie servant à effacer les traces de meurtre, petit à petit elle est devenue une organisation"},{"type":"p","text":"autour de l’assassinat et de la torture et a fini par rester sur le soutien logistique aux mafias et autres"},{"type":"p","text":"criminels de tout poil."},{"type":"p","text":"Whiteman est le roi des informateurs, son réseau est vaste et très implanté, s’il se paye des airs de"},{"type":"p","text":"gentleman presque pacifique, il assure aux corporations, aux mafias et au crawlers un certain"},{"type":"p","text":"équilibre en se plaçant entre commanditaires et exécutants. Il détient une grande partie des serveurs"},{"type":"p","text":"dédiés aux transactions sécurisées sur l’Holonet entre crawlers et leurs employeurs afin de"},{"type":"p","text":"supprimer au mieux les interactions intempestives et les fixers indépendants."},{"type":"p","text":"On sait peu de chose sur cet homme, bien qu’à la tête d’une organisation semi-légale souvent liée"},{"type":"p","text":"aux assassinats, il ne semble pas avoir un passif dans le métier ni jamais avoir été informateur pour la"},{"type":"p","text":"police, on ne lui connait aucun gang ni lien dans une mafia en dehors de ceux qu’il possède depuis"},{"type":"p","text":"qu’il est à la Blanchisserie."},{"type":"p","text":"Burton ne semble pas avoir de vie en dehors des locaux qu’il possède, très respectueux, serein et"},{"type":"p","text":"courtois, il tranche énormément avec nombre d’assassins et de mercenaires qui viennent à lui."},{"type":"p","text":"quelqu’un de proche de Burton, assez proche pour le traumatiser et lui donner l’envie de moderniser"},{"type":"p","text":"le système de la Blanchisserie."},{"type":"p","text":"Officiellement, si Burton est connu de la police et associé avec les mafieux et criminels, la"},{"type":"p","text":"Blanchisserie est une corporation très officielle de nettoyage et récupération de données, Burton,"},{"type":"p","text":"quant à lui, est à la fois un corporatiste et un crawler."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"On suspecte que le manque d’information et de fiabilité dans ce genre de métiers a coûter la vie à"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-adam-nevine-qigang-xuyin-carmello-shen","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Adam NEVINE, Qigang XUYIN, Carmello SHEN","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers"],"pnj":{"completeness":"detailed","real_name":"Adam NEVINE, Qigang XUYIN, Carmello SHEN","identity_keys":["Adam NEVINE, Qigang XUYIN, Carmello SHEN","L’omniscient"],"statut":"fixers","organisation":"Fixers","age":"38 ans","nationalite":"sino-mexicain"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Adam NEVINE, Qigang XUYIN, Carmello SHEN"],["Alias / désignation","L’omniscient"],["Âge","38 ans"],["Affiliations","fixers"],["Nationalité d’origine","sino-mexicain"],["Famille Crawler","Fixers"],["Sous-type","Fixers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Hailey Powell"],["Isaiah Burton"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Prestigieux diplômé de grandes écoles de commerce et management, il se destinait à un poste de"},{"type":"p","text":"PDG d’une grande entreprise en quelques décennies, choisissant Nexstar media, il progressa à une"},{"type":"p","text":"vitesse jamais vue dans le groupe médiatique."},{"type":"p","text":"Manageur de génie, ce fin tacticien avait le nez pour les bons plans, les tendances dotées d’un talent"},{"type":"p","text":"énorme pour la discussion, son éloquence, son charisme et sa belle gueule le menèrent à se faire une"},{"type":"p","text":"belle place dans le groupe."},{"type":"p","text":"La guerre était un point pivot pour le projeter au plus proche du sommet, n’étant pas journaliste, il"},{"type":"p","text":"n’avait aucune raison de s’y rendre en personne et était assez riche pour contourner la conscription"},{"type":"p","text":"qui fut imposée après les massacres du début de guerre."},{"type":"p","text":"Pendant les crises écologiques et financières, il demeura bien installé, mais tout bascula avec"},{"type":"p","text":"l’Holonet et le logifate, Gabriella AUSTIN, directrice du groupe devenu une grande corporation,"},{"type":"p","text":"s’assura de bazarder toute une partie de sa direction pour assainir son empire médiatique, dans le"},{"type":"p","text":"lot, Adam fut recalé par son logifate, le déterminant comme dangereux pour le groupe –"},{"type":"p","text":"supposément- dangereux pour Gabriella et ses plus proches collaborateurs."},{"type":"p","text":"Jeté du jour au lendemain à la rue, sans statut ni aucune forme de compensation financière étant «"},{"type":"p","text":"dangereux » pour la société, il se retrouva à aider les prémices des crawlers à négocier avec des"},{"type":"p","text":"connaissances dans les corporations. Il devint un intermédiaire pour survivre, se refusant à se salir les"},{"type":"p","text":"mains lui-même, organisant donc les mercenaires, sans participer."},{"type":"p","text":"Comme dit précédemment, c’était un tacticien de génie, alors assez vite, en jonglant sur les contrats,"},{"type":"p","text":"les bonnes équipes, prenant les bonnes personnes dans son réseau, il se fit un nom et une certaine"},{"type":"p","text":"fortune."},{"type":"p","text":"Loin d’être idiot, c’est néanmoins une personne assez dangereuse, désormais, il n’a plus aucun égard"},{"type":"p","text":"pour la vie humaine, les crawlers sont des pions et els corporatistes des pourris."},{"type":"p","text":"Il négocie régulièrement avec BURTON, de la blanchisserie, s’occupant des quartiers nord. Il ne"},{"type":"p","text":"donne pas toujours le même nom à ses crawlers, les plus communs sont « Adam », « Carmello » et"},{"type":"p","text":"« Qi », probablement pour les utiliser plus aisément s’il doit les opposer."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-brittany-smith-cavaletty","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Brittany SMITH-CAVALETTY","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers"],"pnj":{"completeness":"detailed","real_name":"Brittany SMITH-CAVALETTY","identity_keys":["Brittany SMITH-CAVALETTY","Lady opium"],"statut":"fixers","organisation":"Fixers","age":"21 ans","nationalite":"américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Brittany SMITH-CAVALETTY"],["Alias / désignation","Lady opium"],["Âge","21 ans"],["Affiliations","fixers"],["Nationalité d’origine","américaine"],["Famille Crawler","Fixers"],["Sous-type","Fixers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Veronica SILVER"],["Corveo LUCIANO"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Brittany n’est pas quelqu’un qui brille par son éducation, sans études et sans talent, elle n’avait que 7"},{"type":"p","text":"ans quand la guerre a été déclarée, une quinzaine d’années quand l’Holonet et les corporations ont"},{"type":"p","text":"mené au bond technologique."},{"type":"p","text":"Dotée d’une valeur de logifate moyen voire médiocre sans pour autant être hors catégorie, elle était"},{"type":"p","text":"destinée à des petites tâches ingrates mais c’était sans compter sa beauté."},{"type":"p","text":"Si Brittany passe encore pour la dernière des gourdes et n’a pas l’air de briller d’intelligence, elle"},{"type":"p","text":"resplendit par sa plastique et son visage charmant. C’est par sa beauté qu’Enzo CAVALETTY, un capo"},{"type":"p","text":"de la mafia Italienne à San Francisco. Mariés en quelques mois à peine, la jeune femme découvrit le"},{"type":"p","text":"luxe et la puissance, rendant fou d’elle son mafieux d’époux."},{"type":"p","text":"Hélas, après un an de mariage, il fut assassiné et ses rivaux s’occupèrent de prendre sa place,"},{"type":"p","text":"dégageant ses hommes les plus loyaux et ne s’encombrant pas d’une gamine jouant la veuve."},{"type":"p","text":"Avec quelques hommes de paroles, elle se réfugia à Los Angeles et demanda la protection de"},{"type":"p","text":"Veronica Silver pour fuir les assassins la poursuivant, en ayant un peu trop vu selon le successeur de"},{"type":"p","text":"son défunt mari. S’adressant à la bonne personne, elle fut donc sauvée et blanchie auprès du Parrain"},{"type":"p","text":"suprême."},{"type":"p","text":"Elle ne put intégrer la mafia italienne, cependant, avec son argent et ce qu’elle avait appris, Brittany"},{"type":"p","text":"s’imposa dans le sud de Los Angeles comme Fixer, au début, elle engageait surtout les crawlers pour"},{"type":"p","text":"le compte de la mafia, comme une simple secrétaire mais assez vite, elle comprit le fonctionnement"},{"type":"p","text":"et se montra plus fûtée qu’elle ne le semblait, se détachant des mafieux pour faire l’intermédiaire"},{"type":"p","text":"avec bien d’autres factions."},{"type":"p","text":"Amoureuse de Veronica Silver depuis leur rencontre, elle estime qu’elle lui doit sa vie bien que la"},{"type":"p","text":"blonde n’en ait rien à foutre, ce n’était qu’un boulot comme un autre."},{"type":"p","text":"Elle joue énormément sur son apparence, les crawlers la pensent généralement être le pantin d’un"},{"type":"p","text":"vrai fixer, la méprisant ou la malmenant, le payant assez cher en général, après coup."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-shuren-shi","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Shuren SHI","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers","Hookers"],"pnj":{"completeness":"detailed","real_name":"Shuren SHI","identity_keys":["Shuren SHI","Lady opium"],"statut":"hookers","organisation":"Fixers","age":"38 ans","nationalite":"chinoise"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Shuren SHI"],["Alias / désignation","Lady opium"],["Âge","38 ans"],["Affiliations","hookers"],["Nationalité d’origine","chinoise"],["Famille Crawler","Fixers"],["Sous-type","Hookers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Wei SHI"],["Zhang TAO"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Membre éminent de la propagande du Parti, elle se fit capturée pendant la guerre et se retrouva"},{"type":"p","text":"vendue aux mafias russes."},{"type":"p","text":"Prostituée elle fut ensuite vendue aux Triades où son génie ne l’empêcha pas d’être maltraitée mais"},{"type":"p","text":"lui octroya l’oreille des principaux chefs."},{"type":"p","text":"Bien que Shuren soit soumise aux mafieux, elle reste une Crawler du sexe et ne pratique pas elle￾même une activité criminelle puisque la prostitution en Grande Californie est légale."},{"type":"p","text":"Disposant d’un pouvoir délégué par les Triades qui leur vient d’un accord avec la mafia russe, elle"},{"type":"p","text":"gère certains quartiers et établissements de plaisir du côté des quartiers chinois."},{"type":"p","text":"Ancienne maitresse de la propagande, elle est extrêmement douée pour vendre ses « produits » et"},{"type":"p","text":"attirer les clients au point qu’elle est plutôt effrayante."},{"type":"p","text":"Les nombreux établissements qu’elle détient sont faciles d’accès quoi que souvent dans des quartiers"},{"type":"p","text":"pauvres ou abandonnés."},{"type":"p","text":"Outre ses talents pour la publicité, elle est incroyablement insidieuse et douée pour persuader,"},{"type":"p","text":"quand elle fit son reportage dessus si elle n’avait pas été aidée."},{"type":"p","text":"Shuren est une femme pleine de surprises, les prostituées sont des crawlers douées pour"},{"type":"p","text":"l’infiltration, elles ne sont pas furtives, mais on les invite toujours où elles veulent entrer servant"},{"type":"p","text":"d’espionne et d’outil de chantage très efficace."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"certains disent que sans elle, Wei SHI, son ancienne camarade, aurait moins duré dans la Triade"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-zeeka-steele","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Zeeka STEELE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers","Hookers"],"pnj":{"completeness":"detailed","real_name":"Zeeka STEELE","identity_keys":["Zeeka STEELE","Lady opium"],"statut":"hookers","organisation":"Fixers","age":"24 ans","nationalite":"américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Zeeka STEELE"],["Alias / désignation","Lady opium"],["Âge","24 ans"],["Affiliations","hookers"],["Nationalité d’origine","américaine"],["Famille Crawler","Fixers"],["Sous-type","Hookers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Robert HAMILTON"],["Ryan BURTON"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Bien qu’assez jeune, Zeeka est possiblement une des « Hookers » les plus réputée de tous Las Vegas"},{"type":"p","text":"bien qu’elle traine à l’occasion à Los Angeles."},{"type":"p","text":"Elle est invitée par presque tous les grands riches de Sincity, elle est la beauté qu’on a le plaisir"},{"type":"p","text":"d’avoir pour présenter les cérémonies ou faire l’accueil, elle est capable de s’adapter à toutes les"},{"type":"p","text":"ambiances, très à l’aise chez les neopunk aussi bien que les ultrariches elle possède une garde-robe"},{"type":"p","text":"colossale pour faire au mieux et ses cheveux, sa peau changent de couleur selon les envies et les"},{"type":"p","text":"besoins."},{"type":"p","text":"Elle a très peu de scrupules et joue de son charme à loisir pur être de toutes les festivités, les"},{"type":"p","text":"réceptions les évènements, on la voit au bras de nombreuses personnalités du divertissement"},{"type":"p","text":"comme du sport ou de la politique."},{"type":"p","text":"C’est une crawleuse jet-setteuse il ne faut pas y voir une catégorie rare, c’est vraiment son cas"},{"type":"p","text":"particulier qui la rend aussi célèbre et les mauvaises langues se laissent souvent aller à dire que si elle"},{"type":"p","text":"avait eu le moindre don artistique elle aurait été plus encore connue."},{"type":"p","text":"Sans être vraiment une espionne, elle est un contact des plus grands fixers de toute la Californie, et"},{"type":"p","text":"réceptions et d’évènement, elle a toujours de bons contacts un peu partout. Loin d’être une"},{"type":"p","text":"prostituée vaguement espionne, elle est à la tête d’un réseau d’informations qui surclasse tout ce"},{"type":"p","text":"qu’un pauvre fixer peut espérer par la simple discussion."},{"type":"p","text":"Elle méprise assez ces derniers, d’ailleurs, maintenant qu’elle ne passe plus par eux, elle favorise les"},{"type":"p","text":"prises de contact avec les autres crawlers avant les fixers, qui, pour elle, ne sont que des"},{"type":"p","text":"intermédiaires inutiles et peu fiables."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"pour cause, elle connait absolument toutes les rumeurs et comme elle assiste à énormément de"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-jacob-delisle","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Jacob DELISLE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers","Hookers"],"pnj":{"completeness":"detailed","real_name":"Jacob DELISLE","identity_keys":["Jacob DELISLE","Le chippendale alpha"],"statut":"Hookers","organisation":"Fixers","age":"31 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Jacob DELISLE"],["Alias / désignation","Le chippendale alpha"],["Âge","31 ans"],["Affiliations","Hookers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Fixers"],["Sous-type","Hookers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Tokala"],["Tia REYNOLDS"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Jacob est le genre de personne né avec beaucoup trop de dons et bien trop peu de volonté. Tombeur"},{"type":"p","text":"invétéré pendant le collège et le lycée, il n’a jamais réussi son diplôme de fin d’étude, trop attiré par"},{"type":"p","text":"les femmes, sa mère essaya de le calmer par de puissants médicaments, à moitié shooté"},{"type":"p","text":"constamment, incapable de suivre, il quitta le lycée et la maison familial pour se livrer à la liberté la"},{"type":"p","text":"plus totale dès ses 17 ans. Sans abris, on le récupéra assez vite par hasard pour en faire un acteur"},{"type":"p","text":"porno, une actrice le sortant de la rue."},{"type":"p","text":"Il ne fit pas une grande carrière comme acteur, peinant à se tenir, mais devint chippendale, un"},{"type":"p","text":"stripteaser, adorant être le fantasme des femmes comme des hommes. Il fut d’ailleurs engagé"},{"type":"p","text":"spécifiquement par le Casino de James EDWARDS, situé dans la réserve indienne de Colorado River."},{"type":"p","text":"C’est ainsi qu’il rencontra une jeune croupière appelée Tokala."},{"type":"p","text":"Lors de la fermeture du casino, il retourna à la rue quelques années. Pendant la guerre, il fit tout"},{"type":"p","text":"pour éviter la conscription, ne voulant surtout pas se battre, se plaçant sous la coupe de mafieux"},{"type":"p","text":"pour y échapper quand il fut tiré au sort, il se retrouva danseur pour la mafia russe en Californie"},{"type":"p","text":"avant que celle-ci ne se fasse déchiqueter par un Ukrainien nommé Drasko VLADIC, pour le compte"},{"type":"p","text":"de la véritable Bratva."},{"type":"p","text":"Excessivement beau et séduisant, doté d’un charme animal, Jacob se retrouva malgré lui le chien des"},{"type":"p","text":"Russes, devenant un pion qu’ils envoyaient à loisir dans les lits des corporatistes ou leurs épouses"},{"type":"p","text":"afin de piéger ou glaner des informations."},{"type":"p","text":"Bien qu’excessivement peu concentré de nature, jacob fit son trou dans les crawlers, les Hookers,"},{"type":"p","text":"plus précisément, devenant une véritable légende, certains disant qu’aucune femme hétérosexuelle"},{"type":"p","text":"ni aucun homme homosexuel ne pouvait lui résister, le fait qu’on l’ait souvent vu dans les Native"},{"type":"p","text":"Casino », une branche de la Tala corporation, très à l’aise avec la terrifiante Tokala a probablement"},{"type":"p","text":"beaucoup joué sur sa « légende »."},{"type":"p","text":"N'en reste pas moins qu’il est véritablement influent et qu’il est vrai qu’il est efficace quant à faire"},{"type":"p","text":"parler les gens qu’il tente de charmer. Il a déjà travaillé avec Tia REYNOLDS, une mercenaire et on l’a"},{"type":"p","text":"déjà vu faire potiche dans une émission culinaire de Svetlana."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-henry-edwards","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Henry EDWARDS","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers","Gunwatchers"],"pnj":{"completeness":"detailed","real_name":"Henry EDWARDS","identity_keys":["Henry EDWARDS","Le Fossoyeur d’enquêtes"],"statut":"Gunwatchers","organisation":"Fixers","age":"51 ans","nationalite":"Americaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Henry EDWARDS"],["Alias / désignation","Le Fossoyeur d’enquêtes"],["Âge","51 ans"],["Affiliations","Gunwatchers"],["Nationalité d’origine","Americaine"],["Famille Crawler","Fixers"],["Sous-type","Gunwatchers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Veronica SILVER"],["Franklin BENTLEY"],["Calvin EDWARDS"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Ancien détective du LAPD, il formait une équipe de choc avec John SILVER, le père de Veronica"},{"type":"p","text":"SILVER, après la mort cruelle de ce dernier en 2013, il n’est pas resté longtemps à la police, son"},{"type":"p","text":"comportement se détériorant, il se brouilla avec ses partenaires mais aussi ses anciens camarades,"},{"type":"p","text":"préférant devenir un détective privé."},{"type":"p","text":"S’en voulant pour la mort de son partenaire, il essaya d’être un mentor pour Veronica, mais ses"},{"type":"p","text":"tendances violentes, alcooliques ne furent pas d’une grande aide, la protection de l’enfance ne laissa"},{"type":"p","text":"pas Veronica entre ses mains et bien qu’il restât dans son entourage, cet échec le ravagea un peu"},{"type":"p","text":"plus."},{"type":"p","text":"Il passa les évènements telle que la guerre, le big One et d’autres, mais le métier de détective devint"},{"type":"p","text":"de moins en moins utile, la survie devenant primordiale, l’argent manquant, les gens n’y faisaient"},{"type":"p","text":"plus appel. Il passa donc sa vie à de petits contrats en tout genre avant le bond technologique."},{"type":"p","text":"Bien qu’officiellement à la retraite en tant que détective, à 51 ans, il continue de prendre des affaires"},{"type":"p","text":"bien qu’il ait réussit à mettre de côté pour ne pas avoir à le faire, tout comme la Silver."},{"type":"p","text":"Il possède un vaste réseau au sein de la police et des informateurs, la pègre le respecte assez"},{"type":"p","text":"réputation que par son lien avec la Silver."},{"type":"p","text":"Edwards s’étant retiré, il prend très peu de cas, le plus souvent, les jeunes femmes ont une chance"},{"type":"p","text":"de l’émouvoir, mais le reste n’a absolument aucune chance."},{"type":"p","text":"Il évite énormément les conflits avec la pègre ou les corporations, en revanche, il s’est spécialisé dans"},{"type":"p","text":"les cas impliquant les forces de police ou les militaires, ayant une dent contre eux, considérant la"},{"type":"p","text":"mort de son « frère », son ami John SILVER, comme relevant de la faute de la corruption."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"également bien qu’on suspecte qu’elle le considère comme intouchable moins par sa seule"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-josefin-drescher","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Josefin DRESCHER","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers","Gunwatchers"],"pnj":{"completeness":"detailed","real_name":"Josefin DRESCHER","identity_keys":["Josefin DRESCHER","le limier allemand"],"statut":"Gunwatchers","organisation":"Fixers","age":"40 ans","nationalite":"Allemande"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Josefin DRESCHER"],["Alias / désignation","le limier allemand"],["Âge","40 ans"],["Affiliations","Gunwatchers"],["Nationalité d’origine","Allemande"],["Famille Crawler","Fixers"],["Sous-type","Gunwatchers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Tokala"],["Razvan LUPESBEI"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Emigrée européenne, cette allemande est venue aux Etats-Unis peu avant la guerre, originellement"},{"type":"p","text":"engagée au BFU (Bundesstelle für Flugunfalluntersuchung), elle a été associée au NTSB lors d’un"},{"type":"p","text":"crash d’avion près d’une réserve indienne notamment."},{"type":"p","text":"Pendant la guerre, elle est demeurée au NTSB comme collaboratrice avant que les conséquences"},{"type":"p","text":"économiques de la guerre ne poussent à la fermeture du Bureau."},{"type":"p","text":"Elle se fit engager comme détective privée en attendant de pouvoir partir mais resta en Californie."},{"type":"p","text":"Josefin possède des augmentations sensitives, une vue améliorée mais encore plus des oreilles et un"},{"type":"p","text":"nez digne d’un chien, elle a également des os extensibles et un modulateur de voix. Elle est connue"},{"type":"p","text":"pour avoir la capacité de sentir le stress et le mensonge, suivre des pistes olfactives et pratiquer des"},{"type":"p","text":"écoutes."},{"type":"p","text":"Elle dispose d’un équipement de pointe et cette scientifique rigoureuse et ordonnée est une"},{"type":"p","text":"véritable machine quand elle est sur une enquête, apte à réaliser des analyses poussées elle-même,"},{"type":"p","text":"elle assure un secret total à ses clients quant aux résultats obtenus. En tant que détective elle est loin"},{"type":"p","text":"d’égaler la Silver mais possède une renommée qui n’est plus à faire malgré tout."},{"type":"p","text":"Dès qu’un élément surnaturel semble jouer dans une affaire, elle la délaisse, son esprit rationnel"},{"type":"p","text":"semble la pousser à se concentrer sur des affaires très simples et terre-à-terre. Elle déteste les"},{"type":"p","text":"affaires mafieuses également du fait d’une intégrité maladive, préférant essentiellement celles"},{"type":"p","text":"corporatistes ou privées."},{"type":"p","text":"Josefin est une femme indépendante qui serait connue pour avoir des liens avec la très célèbre"},{"type":"p","text":"corporatiste Tokala, directrice de la Tala corporation."},{"type":"p","text":"Par ses liens avec les corporations, Josefin est assez mal vue par les autres crawlers la voyant comme"},{"type":"p","text":"une chienne servile du système, cependant, il se pourrait qu’elle cache bien des facettes sur sa vraie"},{"type":"p","text":"nature et ses idéologies sincères derrière un masque de rigueur."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-stella-hardin","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Stella HARDIN","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Fixers","Gunwatchers"],"pnj":{"completeness":"detailed","real_name":"Stella HARDIN","identity_keys":["Stella HARDIN","La sombre hyène de Sacramento"],"statut":"Gunwatchers","organisation":"Fixers","age":"27 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Stella HARDIN"],["Alias / désignation","La sombre hyène de Sacramento"],["Âge","27 ans"],["Affiliations","Gunwatchers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Fixers"],["Sous-type","Gunwatchers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Stella est née dans une famille humble en 2008, à Sacramento."},{"type":"p","text":"Son père était un agent de sécurité tout à fait normal sans histoire, bossant pour un centre"},{"type":"p","text":"commercial. Alors qu’elle avait 14 ans, son père fut arrêté pour meurtre, retrouvé par la police"},{"type":"p","text":"pendant la nuit, le vigile avait massacré quatre jeunes tentant de pénétrer dans le centre commercial"},{"type":"p","text":"après sa fermeture."},{"type":"p","text":"Thomas, le père de Stella, jura qu’il ne les avait pas tués, qu’ils étaient déjà morts mais toutes les"},{"type":"p","text":"preuves l’accablèrent, c’est à cette époque que Stella commença à nourrir une profonde passion"},{"type":"p","text":"pour l’enquête, croyant son père, elle passa les huit années suivantes à chercher des preuves de son"},{"type":"p","text":"innocence. Son beau-père, le nouveau compagnon de sa mère était un pervers, ce qui poussa Stella"},{"type":"p","text":"plus encore à s’éloigner de sa mère."},{"type":"p","text":"Elle réussit haut la main l’examen de police à Sacramento, cependant, après quelques années de"},{"type":"p","text":"service, elle fut virée en 2030, à 22 ans, car on la trouva à fouiller les archives pour ses recherches"},{"type":"p","text":"personnelles. Elle pensait se refaire vite mais le choc technologique se manifesta brutalement et"},{"type":"p","text":"l’instauration du logifate la grilla dans de très nombreux domaines, son envie d’innocenter son père"},{"type":"p","text":"ayant tourné à l’obsession."},{"type":"p","text":"A la mort de son père, suicidé en 2031, elle chercha à reprendre contact avec sa mère, mais ne la"},{"type":"p","text":"trouva pas, elle débuta une nouvelle enquête et commença à joindre des pistes entre es deux"},{"type":"p","text":"affaires l’obsédant, réalisant que son beau-père était le point commun. Après avoir buté ce dernier,"},{"type":"p","text":"de sang-froid en réalisant qu’il était coupable pour le piège de son père et la mort présumée de sa"},{"type":"p","text":"mère, elle s’installa à Los Angeles pour fuir Sacramento et débuter sa vite de « Gunwatcher », ; de"},{"type":"p","text":"détective privé donc, bossant pour plusieurs fixers comme informatrice."},{"type":"p","text":"Souvent, ses missions se résument à chercher des crawlers ayant foiré des contrats, au besoin les"},{"type":"p","text":"piéger pour les ramener à leurs fixers afin qu’ils ne payent les pots cassés, parfois elle est habilitée à"},{"type":"p","text":"les tuer sur place même si son job est essentiellement l’enquête."},{"type":"p","text":"Elle est assez obsessionnelle et croit au paranormal, elle traquerait un certain Novak GYORGY, un"},{"type":"p","text":"riche hongrois, l’accusant de ne pas être humain, probablement un monstre pervers comme bien des"},{"type":"p","text":"corporatistes."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-karl-henry","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Karl HENRY","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Deathrunners"],"pnj":{"completeness":"detailed","real_name":"Karl HENRY","identity_keys":["Karl HENRY","Super héros Californien"],"statut":"Deathrunners","organisation":"DeathRunners","age":"41 ans","nationalite":"Americaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Karl HENRY"],["Alias / désignation","Super héros Californien"],["Âge","41 ans"],["Affiliations","Deathrunners"],["Nationalité d’origine","Americaine"],["Famille Crawler","DeathRunners"],["Sous-type","Deathrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Hailey POWELL"],["Leslie WRIGHT"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Karl Henry est un des plus grands héros de la guerre de Corée du nord."},{"type":"p","text":"Il est possiblement le plus célèbre après Dina, Siobhain et quelques autres."},{"type":"p","text":"Officiellement surnommé « A-Man », c’est l’humain le plus augmenté au monde, il dispose de"},{"type":"p","text":"tellement de modifications qu’il n’a pratiquement plus rien d’origine sur lui."},{"type":"p","text":"Héros national en Californie, régulièrement il participe aux parades commémorant les évènements"},{"type":"p","text":"tragiques et marquants des dernières décennies, c’est une célébrité connue de tous, les jouets d’A￾man sont presque aussi vendus que les poupées Siobhain chez les enfants."},{"type":"p","text":"Soutenu par Raven Industries, il est à la fois le pion de la megacorporation pour promouvoir ses"},{"type":"p","text":"armements et à la fois le pantin du gouvernement pour valoriser la supériorité de ses soldats."},{"type":"p","text":"Plus grand drogué aux Neurostabilisateurs, on ne connait pas officiellement plus modifié que lui,"},{"type":"p","text":"personne de Hailey Powell peu avant la génération de Henry, hélas aucun autre soldat de ce"},{"type":"p","text":"programme n’ayant survécu à la charge neuronale que cela imposait quand ils ne sont simplement"},{"type":"p","text":"pas mort au combat."},{"type":"p","text":"Henry reste un crawler, quand il ne sert pas de pantin, il s’avère même un excellent combattant, un"},{"type":"p","text":"garde du corps réputé par exemple."},{"type":"p","text":"Il a énormément de mal à trouver sa place en revanche, il a même du mal à savoir s’il est encore"},{"type":"p","text":"humain et le plus souvent ne sait pas vraiment qui il est, ne se reconnaissant même plus dans le"},{"type":"p","text":"miroir. Ses crises de rage sont régulièrement cachées, chez lui et les autorités comme Raven"},{"type":"p","text":"industries couvrent beaucoup ses débordements, les N-sta qu’il fument sont mortelles pour les"},{"type":"p","text":"autres augmentés et sa santé pourrait aussi s’en trouver affectée."},{"type":"p","text":"Malgré tout ça, il reste officiellement LE mercenaire le plus puissant et résistant au sein des"},{"type":"p","text":"Crawlers."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"officieusement le « programme Phénix » a produit un soldat encore plus avancé et plus modifié en la"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-hailey-powell","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Hailey POWELL","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Deathrunners"],"pnj":{"completeness":"detailed","real_name":"Hailey POWELL","identity_keys":["Hailey POWELL","le soldat des enfers"],"statut":"Deathrunners","organisation":"DeathRunners","age":"37 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Hailey POWELL"],["Alias / désignation","le soldat des enfers"],["Âge","37 ans"],["Affiliations","Deathrunners"],["Nationalité d’origine","Américaine"],["Famille Crawler","DeathRunners"],["Sous-type","Deathrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Karl HENRY"],["Leslie WRIGHT"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Le record d’augmentations posées sur un corps humain n’est pas détenu par A-man mais par une"},{"type":"p","text":"soldate surnommée « Hell », Hailey Powell."},{"type":"p","text":"Elle n’a été connue qu’après sa mort officielle, par une poignée de scientifiques et d’agents du"},{"type":"p","text":"gouvernement américain puis de celui de Californie, l’information sur le projet autour de la création"},{"type":"p","text":"de soldats cyborgs n’a pas été tenue secrète mais personne n’en a vraiment fait cas avec le bond"},{"type":"p","text":"technologique."},{"type":"p","text":"C’est trois générations de super soldats totalement augmentés qui ont été conçus et dont toutes les"},{"type":"p","text":"innovations faites sur eux sont la base des augmentations actuelles. Hailey était de la toute première"},{"type":"p","text":"génération, elle été le cobaye d’énormément de tests après avoir été sauvée in extremis de la mort."},{"type":"p","text":"Elle a été altérée, réparée, envoyée au front, brisée, réparée, renvoyée dans un cycle sans fin"},{"type":"p","text":"pendant toute la guerre, sortant comme seule survivante de sa génération tandis qu’A-man était de"},{"type":"p","text":"la dernière."},{"type":"p","text":"guerre, en effet, il était impossible d’utiliser des biotechnologies plus récentes pour lui remplacer son"},{"type":"p","text":"corps mécanique par du biologique, moins lourd neuronalement, elle serait morte d’une surcharge"},{"type":"p","text":"neuronale."},{"type":"p","text":"Pourtant, plusieurs crawlers jurent avoir vu une femme répondant à sa description, une crawler"},{"type":"p","text":"bourrées d’augmentations militaires surpuissantes mais surtout dernière génération qu’absolument"},{"type":"p","text":"aucun crawler indépendant n’aurait pu se payer en une vie."},{"type":"p","text":"Hélas, les missions nécessitant une telle force de frappe sont rares, souvent secrètes également, il est"},{"type":"p","text":"corporatiste et préfèrent s’accrocher à la légende de « Hell », qui serait une martyre pour la voie"},{"type":"p","text":"technologique."},{"type":"p","text":"D’autres fous laisseraient entendre qu’elle sert encore le gouvernement, en combattant l’invasion"},{"type":"p","text":"extraterrestre et la remontée des reptiliens venus des entrailles terrestres, comme l’héroïne qu’elle"},{"type":"p","text":"est."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"Officiellement elle est morte dès le début de la guerre, officieusement, elle est morte peu après la"},{"type":"p","text":"probable qu’il s’agisse d’une rumeur issue de crawlers détestant A-man qu’ils trouvent trop"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-jakeline-bates","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Jakeline BATES","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Deathrunners"],"pnj":{"completeness":"detailed","real_name":"Jakeline BATES","identity_keys":["Jakeline BATES","J.B."],"statut":"Deathrunners","organisation":"DeathRunners","age":"27 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Jakeline BATES"],["Alias / désignation","J.B."],["Âge","27 ans"],["Affiliations","Deathrunners"],["Nationalité d’origine","Américaine"],["Famille Crawler","DeathRunners"],["Sous-type","Deathrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"La vie des crawlers n’a rien de simple, Jakie a vu les évènements traumatisants s’enchainer les uns les"},{"type":"p","text":"autres, trop jeune pour aller au combat, elle a simplement subi encore et encore les"},{"type":"p","text":"chamboulements."},{"type":"p","text":"domaines assez différents, cependant elle est réputée avoir un Logifate la classant « hors catégorie »,"},{"type":"p","text":"lui empêchant de postuler des postes à responsabilité ou avec des clients, ce qui réduit aux travaux"},{"type":"p","text":"manuels les plus rébarbatifs."},{"type":"p","text":"Surnommée J.B. dans le milieu, sa réputation n’est plus à faire bien que la majorité des gens"},{"type":"p","text":"s’attendent à ce que J.B. soit un homme."},{"type":"p","text":"Redoutable mercenaire polyvalente, si elle n’a clairement pas la carrure pour faire face lors d’un duel"},{"type":"p","text":"à un Crawler aussi dédié au combat que A-man ou Hell ne l’était, elle n’a absolument rien à lui envier"},{"type":"p","text":"du côté des missions effectuées, son palmarès étant possiblement le mieux rempli de Los Angeles."},{"type":"p","text":"Discrète ou percutante quand il le faut, c’est une tireuse de précision assez douée physiquement,"},{"type":"p","text":"elle est toutefois assez belle et peu aisément faire des missions d’infiltration rien qu’avec son charme"},{"type":"p","text":"tant elle semble douée pour s’adapter à toutes les situations."},{"type":"p","text":"Elle répugne à bosser pour les corporations mais ses missions les plus rentables ont toujours été"},{"type":"p","text":"celles qui les concernaient, évidemment, plus il y a d’argent, plus il y a d’emmerdes."},{"type":"p","text":"Elle a notamment réchappé à la prison-laboratoire sub-aquatique que détenait la corporation Biosun,"},{"type":"p","text":"parvenant à réussir l’extraction de scientifiques y étant retenus par les détenus."},{"type":"p","text":"Comme bien des crawlers, elle a quelques contacts et sait travailler en équipe selon la situation mais"},{"type":"p","text":"travaille généralement seule, on peut toutefois lui rattacher quelques noms comme Dax COOPER ou"},{"type":"p","text":"Riley OWENS, deux crawlers commençant à avoir leur petite réputation dans le milieu et qu’elle"},{"type":"p","text":"aurait sauvé et vaguement conseillé."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"On suspecte que malgré des origines des plus humbles, elle a plusieurs diplômes, dans plusieurs"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-tejana","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Tejana","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Deathrunners"],"pnj":{"completeness":"detailed","real_name":"Tejana","identity_keys":["Tejana","la maitresse des arts"],"statut":"Deathrunners","organisation":"DeathRunners","age":"42 ans","nationalite":"Brésilienne"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Tejana"],["Alias / désignation","la maitresse des arts"],["Âge","42 ans"],["Affiliations","Deathrunners"],["Nationalité d’origine","Brésilienne"],["Famille Crawler","DeathRunners"],["Sous-type","Deathrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Tommy Rosemann"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Une crawler à la réputation énorme, Tejana est connue pour se battre sans armes à feu. On la dit"},{"type":"p","text":"maitresse du jiu-jitsu brésilien et de nombreux arts-martiaux."},{"type":"p","text":"Cette crawler est aussi connue dans le monde des sports de combat qu’en tant que mercenaire."},{"type":"p","text":"Elle a notamment formé Tommy Rosemann qui remporte les matchs de combat libre depuis"},{"type":"p","text":"quelques mois à peine, dans toutes les catégories, tous les styles et à l’heure actuelle, la seule chose"},{"type":"p","text":"qu’il répète aux médias est qu’il n’a pas le niveau de son entraineuse."},{"type":"p","text":"Tejana est une machine de guerre, malgré sa plastique de rêve, elle possède un corps musclé lui"},{"type":"p","text":"octroyant des compétences physiques hors normes, assurément augmentée bien qu’elle le nie, elle"},{"type":"p","text":"ne s’encombre pas souvent d’armes à feu."},{"type":"p","text":"Tejana voyage néanmoins beaucoup, elle ne passe à Los Angeles qu’une fois de temps en temps"},{"type":"p","text":"pour passer du temps avec sa « famille »."},{"type":"p","text":"Malgré une réputation d’artiste martiale imbattable, ce sont moins ses performances aux différents"},{"type":"p","text":"tournois que ses contrats en tant que mercenaires qui poussent à la présenter."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-tia-reynolds","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Tia REYNOLDS","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Cyberthugs"],"pnj":{"completeness":"detailed","real_name":"Tia REYNOLDS","identity_keys":["Tia REYNOLDS","la lionne noire"],"statut":"Deathrunners","organisation":"DeathRunners","age":"32 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Tia REYNOLDS"],["Alias / désignation","la lionne noire"],["Âge","32 ans"],["Affiliations","Deathrunners"],["Nationalité d’origine","Américaine"],["Famille Crawler","DeathRunners"],["Sous-type","Cyberthugs"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Lenny Falks"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Une autre Crawler ayant sa notoriété est Tia Reynolds."},{"type":"p","text":"Elle n’est pas très aimée de ses collègues étant donné qu’à l’instar de A-man, elle est connue pour"},{"type":"p","text":"être régulièrement sous contrat corporatiste, ushkoll essentiellement étant son employeur quand"},{"type":"p","text":"elle sert d’agent de sécurité. Sa personnalité fataliste et détaché ne lui vaut pas d’avoir de nombreux"},{"type":"p","text":"amis, elle ne le cherche pas d’ailleurs, ne gardant contact qu’avec de rares personnes et souvent"},{"type":"p","text":"celles utiles."},{"type":"p","text":"Tia a essentiellement des augmentations sensitives, son passé militaire et son physique athlétique lui"},{"type":"p","text":"permettant d’être une mercenaire extrêmement rapide et puissante sans compensation"},{"type":"p","text":"technologique pour égaler ses adversaires. Elle est une experte en arme et semble dotée d’une"},{"type":"p","text":"patience monstrueuse, capable de mener des missions plusieurs jours absolument seule en dehors"},{"type":"p","text":"des villes, malgré l’environnement et le climat qui sont devenus calamiteux et bien plus rudes."},{"type":"p","text":"Originaire de Portland, elle réside surtout à Los Angeles, son réseau est principalement basé là et se"},{"type":"p","text":"concentre dans le domaine de l’armée, de la sécurité et de la surveillance. Elle a beaucoup d’anciens"},{"type":"p","text":"camarades eux aussi traumatisés n’ayant pas surpassé leur syndrome post-traumatique"},{"type":"p","text":"contrairement à elle et s’étant réfugiés dans les innombrables motards infestant les rouges et"},{"type":"p","text":"villages abandonnés de la Californie. Elle bonne réputation dans le milieu des bikers de fait, hormis"},{"type":"p","text":"chez ceux encore racistes."},{"type":"p","text":"Elle est particulièrement discrète, remplissant assez peu de missions en vérité, du moins les autres"},{"type":"p","text":"crawlers ont bien du mal à déterminer ce qu’elle fait."},{"type":"p","text":"Réputée implacable, Tia assure surtout les missions de chasse à l’homme, elle semble avoir"},{"type":"p","text":"énormément d’expertise dans la recherche de fugitifs et la traque. Elle passe toutefois pour une"},{"type":"p","text":"malade mentale, certains crawlers rapportant qu’à Portland, elle aurait parlé de Loups-garous, un"},{"type":"p","text":"délire qu’on imputerait aisément à son syndrome post-traumatique, rationnalisant un sentiment de"},{"type":"p","text":"paranoïa par une explication surnaturelle."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-carlos-saez","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Carlos SAEZ","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Cyberthugs"],"pnj":{"completeness":"detailed","real_name":"Carlos SAEZ","identity_keys":["Carlos SAEZ","le chacal des gangs"],"statut":"Cyberthugs","organisation":"DeathRunners","age":"26 ans","nationalite":"mexicaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Carlos SAEZ"],["Alias / désignation","le chacal des gangs"],["Âge","26 ans"],["Affiliations","Cyberthugs"],["Nationalité d’origine","mexicaine"],["Famille Crawler","DeathRunners"],["Sous-type","Cyberthugs"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Né en 2009, dans la région du Sinaloa, au Mexique, Carlos est un des crawlers les plus influents de"},{"type":"p","text":"2035 à Los Angeles."},{"type":"p","text":"Dyslexique et grassouillet, le petit Carlos était moqué dans son école religieuse durant son enfance,"},{"type":"p","text":"plus d’une fois, les filles de l’école l’humilièrent et « Rechoncho’los », qu’on pourrait traduire par"},{"type":"p","text":"« Dodu’los » fut victime de ce harcèlement."},{"type":"p","text":"Pendant son adolescence, Carlos continua d’être victime de ses camarades avant de rencontrer"},{"type":"p","text":"Rodrigo POMAR, un enseignant. Rodrigo le tabassa plusieurs fois quand Carlos vint se plaindre des"},{"type":"p","text":"mauvais traitements subis, au lieu de le protéger, il l’enfonça plus salement, pour que la colère de"},{"type":"p","text":"Carlos n’explose, avant de le prendre son aile pour lui faire pratiquer du sport. Carlos gagna"},{"type":"p","text":"rapidement une carrure immense et se lança dans la boxe anglaise."},{"type":"p","text":"Rodrigo géra sa carrière et le fit souvent bosser pour les cartels également, avoir un grand baraqué"},{"type":"p","text":"servant toujours, c’est ainsi qu’on le forma aux armes, pour que le boxer soit un homme de main."},{"type":"p","text":"La carrière de Carlos resta timide, au Mexique, on ne tolérait pas si aisément des athlètes"},{"type":"p","text":"ouvertement gays, encore moins dans les sports de combat où, faute d’adversaire acceptant ses"},{"type":"p","text":"combats, Carlos fut rapidement contraint de vivre de contrats avec les Cartels."},{"type":"p","text":"Il monta un gang au service du Cartel Sinaloa et s’installa à Los Angeles en 2032, devenant un temps"},{"type":"p","text":"le garde du corps de la célèbre Evangelina VERA, une chanteuse-danseuse et actrice sulfureuse, une"},{"type":"p","text":"parfaite couverture pour le chef de gang."},{"type":"p","text":"Il travailla pour plusieurs gangs organisés n’étant pas officiellement du cartel, il n’avait pas"},{"type":"p","text":"spécialement d’allégeance et travailla pour quelques corporations dont la Tuatha par un contrat avec"},{"type":"p","text":"Evangelina."},{"type":"p","text":"On le connait dans le milieu pour être assez impitoyable, surtout avec les femmes, possiblement en"},{"type":"p","text":"raison de son traumatisme d’enfance. Carlos n’est pas un « deathrunner » à sous-estimer quand on"},{"type":"p","text":"engage ce crawler, mieux vaut s’assurer de pouvoir le payer car par ses liens avec les Cartels, son"},{"type":"p","text":"utilisation peut souvent s’avérer plus dangereuse qu’on ne l’imagine, les fixers le redoutant"},{"type":"p","text":"beaucoup et l’évitant."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-kiandra-price","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kiandra PRICE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Cyberthugs"],"pnj":{"completeness":"detailed","real_name":"Kiandra PRICE","identity_keys":["Kiandra PRICE","Redgals queen"],"statut":"Cyberthugs","organisation":"DeathRunners","age":"38 ans","nationalite":"américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kiandra PRICE"],["Alias / désignation","Redgals queen"],["Âge","38 ans"],["Affiliations","Cyberthugs"],["Nationalité d’origine","américaine"],["Famille Crawler","DeathRunners"],["Sous-type","Cyberthugs"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Dina PAGE"],["Saskia"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Née à Compton, en 1997 c’était une camarade de classe de collège et de Lycée de Dina PAGE et"},{"type":"p","text":"même une de ses plus proches amies. Très attirée par les racailles elle a très tôt tourné autour des"},{"type":"p","text":"gangs, notamment des Bloods et affiliés."},{"type":"p","text":"Alors que Dina PAGE perdait son plus jeune frère à cause des gangs, Kiandra se laissait doucement"},{"type":"p","text":"attirer sur cette voie, essayant même d’attirer la future présidente de la Californie dans son gang"},{"type":"p","text":"féminin. Elles eurent plusieurs mots, se battant plusieurs fois, mais Dina apprenant le karaté et ayant"},{"type":"p","text":"un physique plus dynamique de base, elle écrasa Kiandra à chaque confrontation."},{"type":"p","text":"Leurs chemins se séparèrent après le lycée, alors que Dina allait aux jeux olympiques et débutait ses"},{"type":"p","text":"études, Kiandra, enceinte, devait gérer des soucis de drogues et de loyer. Elle fut aussi amenée à"},{"type":"p","text":"gérer la violence de ses partenaires. Pour pouvoir nourrir sa fille, Kaala, elle ne recula devant rien,"},{"type":"p","text":"vendant son corps, volant, tuant même pour intégrer officiellement les Bloods. Les Redgals, son gang"},{"type":"p","text":"de femmes, gagna en réputation, dealant de la drogue sans vergogne pendant la guerre, participant à"},{"type":"p","text":"la destruction du tissu social, kiandra traitant avec toutes sortes de criminels pour préserver sa fille"},{"type":"p","text":"de ce milieu qui lui faisait de plus en plus horreur, réalisant ses erreurs bien trop tard pour une"},{"type":"p","text":"rédemption."},{"type":"p","text":"Jusqu’en 2035, les redgals étaient un outil redoutable pour la pègre, le gang pouvant servir de"},{"type":"p","text":"prostituées, de danseuses aussi bien que de mercenaires, de sentinelles. Kiandra ne gagnait pas des"},{"type":"p","text":"millions malgré tout et se sortit de ses dettes par cet argent aussi facile que sale."},{"type":"p","text":"Offrant sa « protection » à des petits commerces, elle et ses « cyberthugs » qu’étaient les Redgals"},{"type":"p","text":"furent ainsi menées à rencontrer dans l’ancien bar de plage du CocoChuck la nouvelle propriétaire,"},{"type":"p","text":"Saskia. Kianra finit par obtenir sa rédemption inespérée en intégrant la sécurité d’Eversor"},{"type":"p","text":"corporation."},{"type":"p","text":"Toutefois, elle reste un grand nom des gangs non organisés et bien qu’officiellement à Eversorcorp,"},{"type":"p","text":"elle garde un œil sur les affaires de ses « filles »."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-mustafa-dzeko","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Mustafa DZEKO","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Voidrunners"],"pnj":{"completeness":"detailed","real_name":"Mustafa DZEKO","identity_keys":["Mustafa DZEKO","le génie de la lampe"],"statut":"Cyberthugs","organisation":"DeathRunners","age":"40 ans","nationalite":"Bosniaque"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Mustafa DZEKO"],["Alias / désignation","le génie de la lampe"],["Âge","40 ans"],["Affiliations","Cyberthugs"],["Nationalité d’origine","Bosniaque"],["Famille Crawler","DeathRunners"],["Sous-type","Voidrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Mustafa est née en Bosnie-Herzégovine en 1995, juste à la fin des combats après la déclaration"},{"type":"p","text":"d’indépendance de la Bosnie en 1992."},{"type":"p","text":"Il quitta son pays natal en 2021, à 26 ans après une carrière dans les forces de police bosniaques,"},{"type":"p","text":"emmenant sa famille aux Etats-Unis pour fuir la crise de 2021 causées par l’OTAN et la Russie en"},{"type":"p","text":"Bosnie."},{"type":"p","text":"Cependant, être musulman aux Etats-Unis n’était pas chose aisée, errant en ayant du mal à"},{"type":"p","text":"renouveler son droit pour rester sur le sol américain, Mustafa vit sa femme divorcer pour se marier à"},{"type":"p","text":"un New-yorkais, et obtenir la nationalité."},{"type":"p","text":"Immigré illégal finalement, il fut récupéré par quelques organisations criminelles des pays d’Europe"},{"type":"p","text":"de l’Ouest qui sévissaient. Avec sa carrure de brute, il travailla pour les Bosniaques, les Serbes, les"},{"type":"p","text":"Ukrainiens, les Russes, les Bulgares mais aussi les Marocains et d’autres associations criminelles"},{"type":"p","text":"musulmanes."},{"type":"p","text":"Toujours méprisé et jamais intégré, il restait un contact, un associé de loin, formant son propre gang"},{"type":"p","text":"les « Bears » pour satisfaire la demande des criminels ayant besoin de bras sans tremper leurs"},{"type":"p","text":"propres gars."},{"type":"p","text":"Résigner à accomplir n’importe quelle sale besogne, Mustafa s’installa à Los Angeles où les « Bears »"},{"type":"p","text":"avait leur place selon lui, étant donné le drapeau de l’état Californien. Il fut témoins de la « réforme »"},{"type":"p","text":"VLADIC, comme on surnomme l’épuration des mafieux californiens par la Bratva, n’en faisant pas"},{"type":"p","text":"partie, il ne fut même pas inquiété, en vérité, il y participa, ce furent ses premiers contrats de crawler"},{"type":"p","text":"pour la Bratva, surveillant quelques autres mafieux russes et au besoin en tuant quelques-uns pour le"},{"type":"p","text":"compte de VLADIC."},{"type":"p","text":"Mustafa est profondément cynique et désabusé, il n’a pas grand-chose à perdre, considérant son"},{"type":"p","text":"pays d’origine comme fini, n’arrivant pas à rester en couple depuis la trahison de sa femme et"},{"type":"p","text":"n’ayant pas de nouvelle de son fils unique, Kerim, dont il ignore s’il est resté aux Etats-Unis ou non."},{"type":"p","text":"Impitoyable et sanguinaire, les enfants sont la seule chose que Mustafa ne tue pas, ne touche pas et"},{"type":"p","text":"refuse de voir être affectés par les affaires, c’est ainsi qu’en février 2034, il fut même médaillé par"},{"type":"p","text":"Robert HAMILTON pour avoir sauvé des gosses d’un incendie, certes, qu’il avait initié mais la police"},{"type":"p","text":"ne le relia jamais à cet incendie."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-goro-kazuma","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Goro KAZUMA","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Voidrunners"],"pnj":{"completeness":"detailed","real_name":"Goro KAZUMA","identity_keys":["Goro KAZUMA","Le samurai pourpre"],"statut":"Voidrunners","organisation":"DeathRunners","age":"29 ans","nationalite":"japonaise"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Goro KAZUMA"],["Alias / désignation","Le samurai pourpre"],["Âge","29 ans"],["Affiliations","Voidrunners"],["Nationalité d’origine","japonaise"],["Famille Crawler","DeathRunners"],["Sous-type","Voidrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Fuyumi SHINODA"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Goro est né en 2006, à Osaka, au Japon. Il intégra la famille Shinohara, du clan Hakuryu, un des clans"},{"type":"p","text":"des Inagawa kai, le second plus grand groupe yakuza du monde."},{"type":"p","text":"Jusqu’à ses 25 ans, il servit donc fièrement la famille Shinohara, en 2031, néanmoins, lui fut confiée"},{"type":"p","text":"une mission, celle d’assassiner Yoshida SHINODA, un des plus grands membres du groupe"},{"type":"p","text":"Yamaguchi-Gumi."},{"type":"p","text":"L’ironie voulu que cette mission l’épargne, alors qu’il débarquait en Californie, absolument toute la"},{"type":"p","text":"famille Shinohara fut exterminée par un clan du Yamaguchi-gumi. S’en suivit quelques autres"},{"type":"p","text":"massacres dans la digne ligne de conduite du vieil Ishikawa OSHIRO, toujours très sanglant."},{"type":"p","text":"En Californie, sans contact ni argent, son clan anéanti et plus aucun frère de l’inagawa ne voulant"},{"type":"p","text":"prendre contact avec lui, il continua sa mission."},{"type":"p","text":"Faute de moyens pour accéder à l’hôtel Shinoda, se refusant de devenir membre d’un clan ennemi, il"},{"type":"p","text":"se fit connaitre dans les cercles de crawlers, où en tant qu’assassin, il devint progressivement une"},{"type":"p","text":"légende vivante."},{"type":"p","text":"Sa spécialité était les anciens membres de l‘armée nord-coréenne, un peu comme un chasseur de"},{"type":"p","text":"Nazi du siècle précédent, sa détermination et son efficacité brillaient et il fut assez vite remarqué par"},{"type":"p","text":"les yakuzas locaux."},{"type":"p","text":"Un peu malgré lui, il se retrouva à avoir leur amitié et fut amené dans la tour Shinoda pour"},{"type":"p","text":"rencontrer le célèbre Ishikawa, véritable daimyo moderne des yakuzas en Californie."},{"type":"p","text":"Il refusa de s’agenouiller face à lui et le défia, le vieux mafieux lui opposant donc la petite Fuyumi"},{"type":"p","text":"SHINODA."},{"type":"p","text":"Aux urgences de l’hôpital San Lazarus, nul ne sait comment un humain pouvait survivre à autant de"},{"type":"p","text":"lacérations mais aux mains de Keysha RICHARDS, le miracle de sa survie se fit et le japonais ne"},{"type":"p","text":"décéda pas de sa rencontre. Considéré comme mort, il est appelé « Goro Sugimoto » par les Yakuza,"},{"type":"p","text":"comme s’il était un autre et aucune forme de représailles n’existent pour sa tentative de meurtre"},{"type":"p","text":"contre l’oyabun suprême. En revanche, il garde une profonde rancœur de cet échec et a multiplié les"},{"type":"p","text":"contrats depuis."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-zoya-ryukana","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Zoya RYUKANA","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Voidrunners"],"pnj":{"completeness":"detailed","real_name":"Zoya RYUKANA","identity_keys":["Zoya RYUKANA","Tchernokill"],"statut":"Voidrunners","organisation":"DeathRunners","age":"21 ans","nationalite":"Ukraino-japonaise"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Zoya RYUKANA"],["Alias / désignation","Tchernokill"],["Âge","21 ans"],["Affiliations","Voidrunners"],["Nationalité d’origine","Ukraino-japonaise"],["Famille Crawler","DeathRunners"],["Sous-type","Voidrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Après le début du conflit russo-ukrainien en 2014, certaines familles ont émigré. Celle de Zoya s’en"},{"type":"p","text":"alla pour le Japon, assez aisée pour y demeurer."},{"type":"p","text":"Sa mère tomba amoureuse d’un policier local et assez vite Zoya naquit. Parfaitement intégrée à"},{"type":"p","text":"Tokyo, sa vie bascula avec la guerre et le renforcement prodigieux des Yakuza qui suivit durant les"},{"type":"p","text":"grandes crises."},{"type":"p","text":"Elle devint une assassine, en effet, on lui laissa le faux choix de payer la dette de son père ou"},{"type":"p","text":"s’occuper d’un politicien récalcitrant, pour la gamine, encore ado qu’elle était, le choix ne semblait"},{"type":"p","text":"pas exister, mais elle fit celui de l’assassinat, absolument tarée dit-on, elle s’infiltra avec pour seule"},{"type":"p","text":"arme un cutter et ses larmes de collégienne et sortit avec la tête de la cible dans son sac à dos."},{"type":"p","text":"Décrite comme inhumaine, elle est une psychopathe en puissance qui raffole de découper ses"},{"type":"p","text":"victimes avec sa lame, un technokatana démesurément large."},{"type":"p","text":"Particulièrement appréciée des yakuzas c’est une assassine implacable et droguée à l’augmentation"},{"type":"p","text":"dont certaines particulièrement affreuses telles que des générateurs de micro-ondes dans les mains"},{"type":"p","text":"qu’elle utilise pour achever les blessés, ou bien encore de l’acide qu’elle injecte par ses ongles."},{"type":"p","text":"Elle est aussi souvent employée par Drasko VLADIC, un compatriote ukrainien qui, tout aussi sadique"},{"type":"p","text":"et taré qu’elle, adore ses méthodes pour punir certains traitres qui ne méritent pas qu’il vienne en"},{"type":"p","text":"personne."},{"type":"p","text":"Assez jeune elle semble apprécier peu de choses et n’est plus très expressive, certains la disent déjà à"},{"type":"p","text":"sa limite d’humanité, n’étant qu’une machine sans vie, les autres n’osent pas se prononcer sur son"},{"type":"p","text":"état, estimant qu’elle est encore assez humaine pour être aussi sadique et destructrice."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-casey-vaughn","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Casey VAUGHN","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers"],"pnj":{"completeness":"detailed","real_name":"Casey VAUGHN","identity_keys":["Casey VAUGHN","Le protecteur pervers"],"statut":"Neurodivers","organisation":"Neurodivers","age":"48 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Casey VAUGHN"],["Alias / désignation","Le protecteur pervers"],["Âge","48 ans"],["Affiliations","Neurodivers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Neurodivers"],["Sous-type","Neurodivers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Saskia"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"« Lolitasex » est le nom d’un des hackers les plus réputés et craints de Terra Umbra."},{"type":"p","text":"Dénommé Casey Vaughn, il est réputé pour sa toxicité et sa perversion, peu de hackers appréciant de"},{"type":"p","text":"travailler avec cet obsédé sexuel. Adorateur des corps féminins bien pourvus, c’est un très grand fan"},{"type":"p","text":"de pornographie, notamment le hardcore."},{"type":"p","text":"C’est très rare qu’une personne d’un âge similaire ait aussi bien prit le train du bond technologique,"},{"type":"p","text":"mais Casey, né à Porto Rico, a toujours su s’adapter à tout et très vite. Repéré tardivement comme"},{"type":"p","text":"doté d’un très grand QI, il a souvent été méprisé et mis de côté jusque-là."},{"type":"p","text":"Se formant seul en autodidacte, il a tout appris sur l’informatique et s’est constamment mis à niveau"},{"type":"p","text":"au fur et à mesure des innovations, embauché dans des boites de sécurité informatique durant les"},{"type":"p","text":"années 2010, il y travailla une longue décennie avant d’être viré."},{"type":"p","text":"Sans filtre aucun, sa façon de dire les choses directement sur lui, sa vie, ses pensées, ce ne sont pas"},{"type":"p","text":"des choses qui étaient appréciées et ne passèrent plus durant les années 2020, pendant la guerre"},{"type":"p","text":"contre la Corée du Nord, face au massacre de soldats américains, il a rejoint un front citoyen de"},{"type":"p","text":"hackers visant à protéger les communications américaines, fortement piratées."},{"type":"p","text":"Il intégra à distance les rangs de la NSA, submergée avant que celle-ci, après la guerre, n’ait plus de"},{"type":"p","text":"budget de la part du Gouvernement et ne soit partiellement vendue aux megacorporations Apexi et"},{"type":"p","text":"Aces. Les restes de la NSA donnèrent des sous-agences mais rien qui ne dura."},{"type":"p","text":"Avec l’Holonet, il se spécialisa dans la défense, créant des » holowalls » impénétrables et devint une"},{"type":"p","text":"triste légende au sein des Hackers, celle d’un « otaku » pervers et sans filtre, minable mais inégalé"},{"type":"p","text":"dans son domaine."},{"type":"p","text":"Récemment engagé par Eversor corporation, il a été séduit par la présidente de la corporation,"},{"type":"p","text":"Saskia, et a obtenu la direction de la branche Holonet de la corporation, lui qu’on décrivait comme un"},{"type":"p","text":"perdant et un asocial."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-rayne-carter","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Rayne CARTER","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers"],"pnj":{"completeness":"detailed","real_name":"Rayne CARTER","identity_keys":["Rayne CARTER","???"],"statut":"Neurodivers","organisation":"Neurodivers","age":"27 ans","nationalite":"Australienne"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Rayne CARTER"],["Alias / désignation","???"],["Âge","27 ans"],["Affiliations","Neurodivers"],["Nationalité d’origine","Australienne"],["Famille Crawler","Neurodivers"],["Sous-type","Neurodivers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["??"],["??"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Rayne CARTER est possiblement l’hacker le plus redouté et admiré de tout Terra Umbra."},{"type":"p","text":"Comme bien des autres son visage n’est pas vraiment connu et on la connait plus par son"},{"type":"p","text":"pseudonyme que son identité réelle."},{"type":"p","text":"Elle est moins jeune et inexpérimentée qu’elle n’y parait, bien au contraire, elle trône au sommet des"},{"type":"p","text":"« cafards », elle s’infiltre absolument partout, aucun système qu’elle n’a attaqué n’a su lui résister,"},{"type":"p","text":"ceux qui n’ont pas encore cédé face à ses talents ne l’ont simplement pas encore affronté."},{"type":"p","text":"Certains la surnomme Excalibur ou lighsaber tant elle est réputée incisive et efficace."},{"type":"p","text":"Elle aurait fui l’Australie avec la progression effrayante du désert et la montée des eaux, les grandes"},{"type":"p","text":"villes du pays se faisant en partie submerger et de nombreux soucis de santé se posant, en plus des"},{"type":"p","text":"infestations de reptiles."},{"type":"p","text":"Elle se serait installée dans neoTokyo en 2032 et l’aurait quitté en 2034 après de sombres affaires"},{"type":"p","text":"entre elle et les yakuzas."},{"type":"p","text":"Bien que l’holonet et les connections directes soit récents, elle semble avoir une capacité à la neuro￾drive sans égale, pouvant piloter des drones en grand nombre."},{"type":"p","text":"Elle a 3 enfants avec son mari, Marcus Brock, fils de Melvin, s’étant mariée pour avoir la nationalité"},{"type":"p","text":"americaine et donc californienne, elle a réveillé dans le frère adoptif de veronica le monstre qui était"},{"type":"p","text":"en son père, l’australienne devenant sa chienne servile et sa femme au foyer, enchainant les grosses"},{"type":"p","text":"et restant à la maison faire à manger pour son mari et ses petites amies."},{"type":"p","text":"Bien évidemment, elle travaillait honnêtement à la Laguna Bank corporation avant d’être virée pour"},{"type":"p","text":"incapacité, la maternité ne comptant plus dans les droits corporatifs."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-domingo-valerio","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Domingo Valerio","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers","Netdrillers"],"pnj":{"completeness":"detailed","real_name":"Domingo Valerio","identity_keys":["Domingo Valerio","L’unique"],"statut":"Neurodivers","organisation":"Neurodivers","age":"29 ans","nationalite":"Mexicain"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Domingo Valerio"],["Alias / désignation","L’unique"],["Âge","29 ans"],["Affiliations","Neurodivers"],["Nationalité d’origine","Mexicain"],["Famille Crawler","Neurodivers"],["Sous-type","Netdrillers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Domingo Alfredo di VALERIO est un hacker de renommée mondiale."},{"type":"p","text":"On connait mal son apparence, tout comme Lolita666, il est un grand amateur d’holoskin et"},{"type":"p","text":"généralement il porte un masque en plus."},{"type":"p","text":"Il s’est surtout fait connaitre pendant la guerre des Corporations au Mexique, les Cartels ont levé"},{"type":"p","text":"toutes les ressources possibles pour survivre, face à l’immense utilisation d’objets connectés par les"},{"type":"p","text":"corporatistes, très vite, les hackers ont pris une part au moins égale aux soldats des Cartels."},{"type":"p","text":"Décoré pour héroïsme par le gouverneur du Sinaloa et président temporaire du mexique, Dante"},{"type":"p","text":"GUZMAN, le jeune Domingo s’installa comme une célébrité et enchaina les petites victoires sur les"},{"type":"p","text":"corporations. Hélas, rien ne dure, il se fit complétement piéger et son erreur mena une grosse perte"},{"type":"p","text":"d’influence du cartel Sinaloa qui ne fut récupérée qu’en vendant ces parcelles à la Californie à"},{"type":"p","text":"l’élection de Dina Page, les retirant des mains corporatistes."},{"type":"p","text":"sait qu’il préféra fuir définitivement à Los Angeles."},{"type":"p","text":"S’il conserve une grande part de son réseau en lien avec le Cartel Sinaloa, Domingo s’est très bien"},{"type":"p","text":"implanté dans la communauté californienne des crawlers."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"Sévèrement puni, on ignore quelle torture Domingo a subi pour son unique échec, en revanche on"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-ashuna-kimble","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ashuna KIMBLE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers","Netdrillers"],"pnj":{"completeness":"detailed","real_name":"Ashuna KIMBLE","identity_keys":["Ashuna KIMBLE","Le nécrohacker"],"statut":"Netdrillers","organisation":"Neurodivers","age":"24 ans","nationalite":"Jamaïquaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ashuna KIMBLE"],["Alias / désignation","Le nécrohacker"],["Âge","24 ans"],["Affiliations","Netdrillers"],["Nationalité d’origine","Jamaïquaine"],["Famille Crawler","Neurodivers"],["Sous-type","Netdrillers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Kendasha ROBERTS"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"La Jamaïque n’est pas le pays dont on parle le plus en général et a sévèrement été touché pendant"},{"type":"p","text":"les grandes crises économiques, sanitaires et écologiques."},{"type":"p","text":"Enormément de jamaïquains ont quitté l’île pour se répartir sur le continent afin de fuir les"},{"type":"p","text":"inondations fréquentes et la montée des flots."},{"type":"p","text":"Ashuna n’avait pas de grande qualité en arrivant aux Etats-Unis, voulant percer dans la musique, elle"},{"type":"p","text":"se fit broyer par le système corporatiste très rodé, devenant la voix d’une starlette du moment."},{"type":"p","text":"Détestant son rôle d’esclave de l’ombre, elle se rapprocha de hackers pour ruiner chaque show où la"},{"type":"p","text":"starlette se donnait en spectacle, de fil en aiguille, apprit d’elle-même comment faire."},{"type":"p","text":"La musique ne l’intéressa pas longtemps, réalisant par son expérience personnelle que la société se"},{"type":"p","text":"fichait bien de vérifier qui faisait quoi, elle se lança dans la « résurrection » de personnes disparues"},{"type":"p","text":"sur l’Holonet, falsifiant les documents, rien ne se faisant plus en présentiel ou presque, elle obtint"},{"type":"p","text":"des primes, des héritages, des biens et des dons sans aucun scrupule."},{"type":"p","text":"Avec son groupe de « charognards », qu’on surnomma les « pokemon » un temps, elle alla plus loin"},{"type":"p","text":"en maintenant en activité des augmentations neuronales de gens récemment décédés, bravant les"},{"type":"p","text":"sécurités corporatives pour piller juste assez d’informations pour faire du chantage ou revendre ça à"},{"type":"p","text":"un informateur intéressé."},{"type":"p","text":"« Pink Ashu » fut renommée la « nécromancienne », possédant des salles entières de corps"},{"type":"p","text":"connectés et reliés à des IA pour assurer une continuité de leurs activités au moins sur l’Holonet."},{"type":"p","text":"Traquée par le LAUS, elle n’est pas sur les listes de criminels les plus recherchés car elle a des accords"},{"type":"p","text":"avec le CBII, le bureau ayant eu besoin de ses compétences pour plusieurs affaires et désormais la"},{"type":"p","text":"couvrant vaguement vis-à-vis de la police."},{"type":"p","text":"Détestée par les corporations de service, elle est, en revanche, très amie avec Kendasha ROBERTS, la"},{"type":"p","text":"plus connue des « charognards », cette dernière lui fournissant des implants frais avec les corps"},{"type":"p","text":"associés, parfaits pour faire « vivre » l’identité de ces morts, juste le temps de les rentabiliser."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-kane-riley","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kane Riley","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers","Netdrillers"],"pnj":{"completeness":"detailed","real_name":"Kane Riley","identity_keys":["Kane Riley","Le menteur"],"statut":"Netdrillers","organisation":"Neurodivers","age":"35 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kane Riley"],["Alias / désignation","Le menteur"],["Âge","35 ans"],["Affiliations","Netdrillers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Neurodivers"],["Sous-type","Netdrillers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Saskia"],["Siobhain nic Siridean"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Avant la guerre contre la Corée du Nord, Kane était encore étudiant quand il s’orienta sur"},{"type":"p","text":"l’informatique et les IA. Plutôt beau, il débuta aussi une carrière de mannequin et d’acteur en"},{"type":"p","text":"parallèle, tournant même dans une des premières séries à succès de Siobhain qui allait devenir la"},{"type":"p","text":"plus célèbre actrice du monde peu après."},{"type":"p","text":"Les crises économiques ravagèrent le pays et les famines, les catastrophes écologiques, tout"},{"type":"p","text":"contribua à une régression technologique précédent l’immense bond issu des brevets de Leslie"},{"type":"p","text":"Wright. Face à la perte en utilité de l’informatique, Kane fut contraint à se prostituer pour survivre"},{"type":"p","text":"dans un Los Angeles ravagé. Bien qu’il parvienne à éviter les partenaires masculins, il fut"},{"type":"p","text":"complétement brisé et humilié par une riche cliente, brisant ses maigres espoirs de reprendre une"},{"type":"p","text":"carrière d’acteur en le traumatisant assez pour finir terrifier à l’idée de se sociabiliser."},{"type":"p","text":"Le lancement de l’Holonet changea le monde et forcément la vie de Kane. Découvrant une réalité"},{"type":"p","text":"virtuelle si proche de celle du quotidien, si aisée d’accès qu’il développa une addiction pour l’holonet,"},{"type":"p","text":"terrifié à l’idée d’interagir dans la réalité mais pas dans l’Holonet."},{"type":"p","text":"Animé d’une colère profonde, il mit à contribution ses savoirs en informatiques pour se venger,"},{"type":"p","text":"attaquant la corporation Datami dont sa tortionnaire était la numéro 2."},{"type":"p","text":"Repéré par Allico il devint un briseur d’holowall, explosant tout système de défense avec une"},{"type":"p","text":"certaine aisance. Engagé par la Tuatha il n’y resta pas longtemps quand un cadre tenta de le faire"},{"type":"p","text":"chanter en le menaçant de révéler son passé"}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-khristina-yaroslavovna","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Khristina YAROSLAVOVNA","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers","Neurokillers"],"pnj":{"completeness":"detailed","real_name":"Khristina YAROSLAVOVNA","identity_keys":["Khristina YAROSLAVOVNA","Le hacker-gamer"],"statut":"Netdrillers","organisation":"Neurodivers","age":"31 ans","nationalite":"russe"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Khristina YAROSLAVOVNA"],["Alias / désignation","Le hacker-gamer"],["Âge","31 ans"],["Affiliations","Netdrillers"],["Nationalité d’origine","russe"],["Famille Crawler","Neurodivers"],["Sous-type","Neurokillers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Saskia"],["Yegor DARMALOV"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Née à Vladivostok en 2004, elle avait seulement 19 ans quand elle a été forcée de quitter la Russie"},{"type":"p","text":"après l’invasion nord-coréenne. Jusque-là, l’étudiante était une streameuse russe plutôt appréciée"},{"type":"p","text":"dans le monde du gaming."},{"type":"p","text":"Hélas pour elle, elle était plutôt mignonne et si ça lui permit de quitter sans frais le continent"},{"type":"p","text":"asiatique, ça lui coûta sa liberté une fois en Californie."},{"type":"p","text":"Radoslav, un membre de la Bratva, la prostitua pour rembourser ses frais d’évacuation et payer ceux"},{"type":"p","text":"de ses parents."},{"type":"p","text":"Afin de gagner plus vite de l’argent, elle se lança dans les compétitions de jeu-vidéos, sa passion"},{"type":"p","text":"initiale, hélas, avec la guerre, elle ne gagna pas beaucoup malgré des victoires."},{"type":"p","text":"En 2030, elle découvrit l’holonet et cette nouvelle façon de naviguer et se connecter aux appareils :"},{"type":"p","text":"le « neurodrive », elle réalisa alors qu’elle avait une capacité à se connecter incroyablement plus"},{"type":"p","text":"poussée que la moyenne et bien qu’elle restât une prostituée, consacra un temps fou aux nouvelles"},{"type":"p","text":"compétitions des nouveaux jeux utilisant cette structure. Elle renoua avec une petite célébrité en"},{"type":"p","text":"tant que « Frigorifreak » et rencontra son petit ami, Yegor DARMALOV, un autre grand joueur,"},{"type":"p","text":"décidant d’incarner à deux le joueur derrière ce pseudonyme."},{"type":"p","text":"Outre les jeux-vidéos, l’environnement holonet permettait à cette jeune femme sans connaissances"},{"type":"p","text":"dans l’informatique de devenir un des plus puissants neurodivers du monde, passant outre els"},{"type":"p","text":"protocoles de sécurité des jeux pour les altérer et remporter compétition sur compétition, hélas"},{"type":"p","text":"réalisant trop tard que l’argent donné à Radoslav ne servait qu’à l’enrichir, la famille de Khristina"},{"type":"p","text":"étant morte depuis bien longtemps sous les assauts coréens."},{"type":"p","text":"Elle avait mis sa santé en jeu en menant des semaines entières de connexion entre quelques clients"},{"type":"p","text":"pour rien et avait développé des tumeurs à cause d’une suractivité neurale, condamné à ne vivre"},{"type":"p","text":"quelques mois encore."},{"type":"p","text":"En début de 2035, toutefois, sa vie changea un jour, Saskia, d’Eversor ayant décidé de la recruter, elle"},{"type":"p","text":"la fit soigner par les meilleurs médecins de Biosun et la nomma cadre supérieur à Eversor net."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-dragoslav-memic","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Dragoslav Memic","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers","Neurokillers"],"pnj":{"completeness":"detailed","real_name":"Dragoslav Memic","identity_keys":["Dragoslav Memic","Hacker de terrain"],"statut":"Neurokillers","organisation":"Neurodivers","age":"34 ans","nationalite":"Roumaine."},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Dragoslav Memic"],["Alias / désignation","Hacker de terrain"],["Âge","34 ans"],["Affiliations","Neurokillers"],["Nationalité d’origine","Roumaine."],["Famille Crawler","Neurodivers"],["Sous-type","Neurokillers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Dragoslav était un type sans ambition, sans compétences, chauffeur pour un clan mafieux, il se"},{"type":"p","text":"retrouva à Paris, en France, à convoyer des prostituées quand il fut arrêté."},{"type":"p","text":"Extradé en Roumanie, il fut racheté pendant la guerre contre la Corée du nord, la Russie rachetant la"},{"type":"p","text":"vie de prisonniers à d’autres pays dans ses propres programmes de recherche cependant le"},{"type":"p","text":"scientifique à la tête du programme bascula chez les Américains et s’occupa d’autres projets."},{"type":"p","text":"Memic se retrouva comme simple soldat."},{"type":"p","text":"En 2025, il est finalement blessé d’une balle dans la tête et sa survie est miraculeuse, récupéré par"},{"type":"p","text":"l’armée américaine, la balle coréenne dans son cerveau est une véritable bombe à retardement"},{"type":"p","text":"pouvant le tuer à tout instant."},{"type":"p","text":"Enchainant les petits boulots, il se paya une opération pour remplacer les parties de cerveau"},{"type":"p","text":"endommagées afin d’extraire ensuite la balle sans séquelles, à une époque où les augmentations"},{"type":"p","text":"commencèrent à devenir courantes."},{"type":"p","text":"Durant l’opération rien ne se passa comme prévu hélas."},{"type":"p","text":"Charcuté par des chirurgiens l’équipe médicale fut abusée par sa fausse identité et paniqua en"},{"type":"p","text":"pensant avoir détruit le cerveau d’un très riche mafieux."},{"type":"p","text":"Opéré d’une très grande part de sa matière grise, il devint un véritable ordinateur, se servant de cet"},{"type":"p","text":"atout à moindre coût pour calculer les probabilités, simuler des situations et réagir plus vite qu’un"},{"type":"p","text":"humain normal. Capable d’anticiper avec une certaine fiabilité, il est capable d’éviter les balles, et"},{"type":"p","text":"anticiper les réactions des autres personnes."},{"type":"p","text":"Hacker de génie, son cerveau avancé fait qu’il est monstrueux pour percer les défenses sécuritaires"},{"type":"p","text":"quand il est sur place, même s’il représente une bien plus grande menace pour les autres augmentés"},{"type":"p","text":"sur les systèmes non humains."},{"type":"p","text":"Il semblerait qu’il soit engagé par une corporation méconnue employant ses capacités surhumaines à"},{"type":"p","text":"des fins mystérieuses."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-zemirah-sherah","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Zemirah Sherah","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers","Neurokillers"],"pnj":{"completeness":"detailed","real_name":"Zemirah Sherah","identity_keys":["Zemirah Sherah","L’hackssassin"],"statut":"Neurokillers","organisation":"Neurodivers","age":"21 ans","nationalite":"Canadienne"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Zemirah Sherah"],["Alias / désignation","L’hackssassin"],["Âge","21 ans"],["Affiliations","Neurokillers"],["Nationalité d’origine","Canadienne"],["Famille Crawler","Neurodivers"],["Sous-type","Neurokillers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Zemirah est la moins augmentée de tous les Hackers de renommée majeure."},{"type":"p","text":"Elle dispose d’un système à distance l’émancipant de toute connectique."},{"type":"p","text":"Né au Canada, cette passionnée d’occultisme est un génie de l’Holonet."},{"type":"p","text":"Elle possède une puissante augmentation décuplant ses signaux et est capable de griller presque"},{"type":"p","text":"n’importe quel circuit par sa seule volonté, c’est l’hacker la plus imparable même si ces capacités de"},{"type":"p","text":"perforation des systèmes complexe ou bien de défense semble être assez moindre comparées aux"},{"type":"p","text":"capacités des autres hackers de renoms, elle a comme force de tout gérer sans avoir jamais besoin"},{"type":"p","text":"de se connecter par câble."},{"type":"p","text":"Cette capacité fait d’elle une assassine d’augmentés également, en effet, elle est capable de griller à"},{"type":"p","text":"distance n’importe quelle augmentation neuronale ou organe artificiel, elle est d’ailleurs connue"},{"type":"p","text":"pour son « Bang », ayant déjà reproduit une scène de jeu vidéo mythique, en plein Los Angeles, tuant"},{"type":"p","text":"net une escouade corporatiste entière comme si elle tirait chacun d’eux en pleine tête, sans utiliser la"},{"type":"p","text":"moindre balle, juste en commandant l’arrêt de certaines fonctions."},{"type":"p","text":"En dehors de ses actions de crawler, elle semble mener une vie aisée contrairement à bien des"},{"type":"p","text":"collègues, ce qui lui vaut une haine rare, il existe très peu de crawlers connaissant son nom n’ayant"},{"type":"p","text":"pas un ressentiment à son égard, non seulement, c’est une tueuse et surtout de crawlers mais c’est"},{"type":"p","text":"aussi une traitresse notoire."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-taishara-jibson","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Taishara JIBSON","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs"],"pnj":{"completeness":"detailed","real_name":"Taishara JIBSON","identity_keys":["Taishara JIBSON","La reine de la casse"],"statut":"Cyppers","organisation":"Meditechs","age":"34 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Taishara JIBSON"],["Alias / désignation","La reine de la casse"],["Âge","34 ans"],["Affiliations","Cyppers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Meditechs"],["Sous-type","Meditechs"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Née en 2001, à Detroit, c’est une mécanicienne de formation qui peinait à trouver un travail ;"},{"type":"p","text":"En déménageant à San Francisco, elle espérait avoir un meilleur boulot et ce fut le cas, elle trouva"},{"type":"p","text":"aisément et se fit ne petite carrière de mécano jusqu’en 2022 où à 21 ans elle décida de s’engager"},{"type":"p","text":"comme mécanicien dans l’armée à la suite de la déclaration de guerre."},{"type":"p","text":"En tant que mécano, dans l’US army, elle ne participa pas autant aux combats qu’elle ne l’imaginait"},{"type":"p","text":"en se faisant engager, mais ce fut pour le mieux étant donné les pertes de l’armée américaines à ses"},{"type":"p","text":"débuts."},{"type":"p","text":"Elle travailla pour le PCRC, le comité scientifique pour la recherche et le développement militaire,"},{"type":"p","text":"non pas comme chercheuse mais simple mécanicienne faisant ce qu’on lui demandait."},{"type":"p","text":"Elle prit un certain plaisir à voir et tester les premières augmentations et même si pour les soldats qui"},{"type":"p","text":"en étaient les testeurs, ce n’était absolument pas joyeux, hurlant de douleur, devenant fou ou bien"},{"type":"p","text":"encore devenant apathique."},{"type":"p","text":"En 2026, elle fut rapatriée pour ses perms, mais elle déserta, se cachant dans les bas quartiers de Los"},{"type":"p","text":"Angeles pour ne pas repartir au front, son plan était de se lancer dans le commerce des"},{"type":"p","text":"augmentations, en bricolant dans son coin sur la base de ses connaissances acquises au PCRC."},{"type":"p","text":"Elle fut moquée et s’endetta grandement avant d’avoir le moindre prototype à proposer, aucune"},{"type":"p","text":"entreprise ne la regarda, comme elle, toutes corporations avaient déjà tout ce qu’il fallait pour"},{"type":"p","text":"développer ces technologies, ne faisant qu’attendre que la société soit assez mure, en 2030."},{"type":"p","text":"Elle gagna sa vie en restant mécanicienne pour les gangs, les motards et une fois les corporations"},{"type":"p","text":"lancées dans la course aux augmentations, continua de faire son beurre en réparant et bidouillant"},{"type":"p","text":"les mécaniques."},{"type":"p","text":"Ses connaissances rudimentaires en soins médicaux, appris au PCRC en faisant l’archétype même des"},{"type":"p","text":"la Meditech."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-phoebe-edgar","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Phoebe EDGAR","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs"],"pnj":{"completeness":"detailed","real_name":"Phoebe EDGAR","identity_keys":["Phoebe EDGAR","Le piment"],"statut":"Meditechs","organisation":"Meditechs","age":"22 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Phoebe EDGAR"],["Alias / désignation","Le piment"],["Âge","22 ans"],["Affiliations","Meditechs"],["Nationalité d’origine","Américaine"],["Famille Crawler","Meditechs"],["Sous-type","Meditechs"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Saskia"],["Connor Shaw"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Phoebe Edgar est née on ne sait où, officiellement, elle a 22 ans et réside à Los Angeles depuis"},{"type":"p","text":"quelques années seulement, 4 à 6 ans."},{"type":"p","text":"Probablement immigrée, elle a toujours résidé dans les quartiers les plus pauvres et délabrés."},{"type":"p","text":"Très liée au gang de motards des « Urban Wolves », on ne sait pas bien quelle relation elle avait à"},{"type":"p","text":"l’origine avec Max Feldon, le président du club à l’époque, si elle était sa régulière et en est venue à"},{"type":"p","text":"réparer ou si elle était sa mécanicienne et est devenue sa régulière…"},{"type":"p","text":"Dans le monde des motards et des neopunks, elle était incontournable, capable de déverrouiller des"},{"type":"p","text":"augmentations sécurisées, réparer à peu près n’importe quel véhicule et même bricoler de A à Z"},{"type":"p","text":"quelques armes ou augmentations de sa propre invention."},{"type":"p","text":"On suppose qu’elle ne possède aucune formation étant donné son caractère rebelle et indiscipliné"},{"type":"p","text":"mais bien des corporations ont cherché à l’avoir."},{"type":"p","text":"Bien qu’elle ne fasse pas officiellement partie de l’insurrection civile, Phoebe reste très proche des"},{"type":"p","text":"neopunk et des insurgés, vivant parmi eux et les équipant, les réparant."},{"type":"p","text":"Elle s’est libérée de ses liens quelque peu exclusifs avec les « Urban wolf » en rencontrant Connor"},{"type":"p","text":"Shaw, célèbre musicien des « Lightning Shadow », le groupe de Leslie Wright, le neopunk ayant"},{"type":"p","text":"explosé les motards avec leurs propres motos."},{"type":"p","text":"Sa création la plus célèbre est le corps de « Raiser », la tête d’affiche des Insurgés, qu’elle modifia"},{"type":"p","text":"elle-même avec différentes augmentations glanées sur des corporatifs et récupérées ci et là. Si Raiser"},{"type":"p","text":"parait grossier à première vue, c’est un des augmentés les plus monstrueux et destructeurs s’il le"},{"type":"p","text":"souhaite grâce au génie de Phoebe."},{"type":"p","text":"Récemment, elle changea son fusil d’épaule et fut engagée par Eversor Corporation à la surprise"},{"type":"p","text":"générale, prenant la tête de la branche « Motors » et de la production de véhicules, travaillant même"},{"type":"p","text":"avec la pilote de renommée internationale : Assandra Mills."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-elizabeth-mircalla-karnstein","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Elizabeth Mircalla KARNSTEIN","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs","Cyppers"],"pnj":{"completeness":"detailed","real_name":"Elizabeth Mircalla KARNSTEIN","identity_keys":["Elizabeth Mircalla KARNSTEIN","La stryge de los Angeles"],"statut":"Meditechs","organisation":"Meditechs","age":"38 ans","nationalite":"Autrichienne"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Elizabeth Mircalla KARNSTEIN"],["Alias / désignation","La stryge de los Angeles"],["Âge","38 ans"],["Affiliations","Meditechs"],["Nationalité d’origine","Autrichienne"],["Famille Crawler","Meditechs"],["Sous-type","Cyppers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Elizabeth était un médecin plutôt connu en Allemagne où elle fit sa carrière bien que née en"},{"type":"p","text":"Autriche."},{"type":"p","text":"En vérité, jusqu’à son émigration aux Etats-Unis, elle semblait plutôt commune, sans autre"},{"type":"p","text":"réputation que celle d’une médecin entêtée bien que détachée et surtout d’être dotée d’un charme"},{"type":"p","text":"glacial mais immense."},{"type":"p","text":"Elle entretint une relation avec le directeur de Rabbitechnologies corporation, Hannes SENEFELDER,"},{"type":"p","text":"de vingt ans son ainé, et le mena au mariage, l’union semblait parfaitement intéressée, RTcorp. Etant"},{"type":"p","text":"une des trois biocorporations leader dans le marché à cette époque."},{"type":"p","text":"Cependant, la femme du directeur n’apprécia pas le projet et fit exécuter la brune sulfureuse. Les"},{"type":"p","text":"crawlers ratèrent leur cible, du moins, elle survécu à ses blessures mais sa clinique privée, sa maison"},{"type":"p","text":"et la majorité de ses amis furent incendiés, on révéla des malversations financières et du trafic"},{"type":"p","text":"d’organes. La police commença à rechercher Elizabeth officiellement, Samanta SENEDELDER mettant"},{"type":"p","text":"le paquet pour anéantir sa rivale, chaque semaine, quelque chose de nouveau s’ajoutait aux charges"},{"type":"p","text":"contre elle tant et si bien que la médecin fut contrainte à disparaitre."},{"type":"p","text":"C’est dans les quartiers abandonnés qu’elle fit sa seconde vie, si les accusations étaient"},{"type":"p","text":"originellement fausses, désormais le trafic d’organes artificiels et réels était à son registre d’activités."},{"type":"p","text":"Elle était dotée de banque de sang et d’ADN prodigieux et se foutant absolument des lois pratiquait à"},{"type":"p","text":"loisir le clonage partiel dans ses laboratoires."},{"type":"p","text":"Elle serait en partie financée par Elody-Katheryn SKOTIA, une directrice de branche à Sunway"},{"type":"p","text":"corporation afin de se venger."},{"type":"p","text":"En dehors de son passé, elle est connue pour être une prédatrice assez efficace ayant un gout très"},{"type":"p","text":"prononcé pour les jeunes femmes et ses tarifs d’opérations varient donc beaucoup selon le client et"},{"type":"p","text":"sa plastique."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-lenny-falk","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Lenny Falk","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs","Cyppers"],"pnj":{"completeness":"detailed","real_name":"Lenny Falk","identity_keys":["Lenny Falk","Le bossu de notre Tech."],"statut":"Cyppers","organisation":"Meditechs","age":"31 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Lenny Falk"],["Alias / désignation","Le bossu de notre Tech."],["Âge","31 ans"],["Affiliations","Cyppers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Meditechs"],["Sous-type","Cyppers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Tia Reynolds"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Lenny a toujours été assez laid et a toujours souffert de diverses difformités et de soucis de santé,"},{"type":"p","text":"fortes suées quasi constantes, allergies, digestion difficile, salive abondante, peu d’odorat pour sentir"},{"type":"p","text":"ses propres odeurs, très grosse ossature…"},{"type":"p","text":"C’est un paria qui a toujours été rejeté pour son physique et ses soucis d’élocutions, profondément"},{"type":"p","text":"meurtri par une enfance et une adolescence extrêmement difficile, sa mère lui acheta un"},{"type":"p","text":"appartement en 2019 pour l’y cacher tel un Quasimodo des temps modernes, refaisant sa vie en ne"},{"type":"p","text":"s’occupant que de mettre un peu d’argent sur son compte, l’abandonnant totalement pour le reste."},{"type":"p","text":"Extrêmement timide, Lenny viva donc reclus et passa des examens dans sa chambre, seuls quelques"},{"type":"p","text":"médecins passant à l’occasion à des frais exorbitant, ainsi que les innombrables livreurs."},{"type":"p","text":"Pour payer ses frais médicaux à domicile, Lenny trouva un moyen, bricolant un drone il se mit à"},{"type":"p","text":"filmer ses voisines et diffuser ça sur un site payant, petit à petit, il trouva sa voie, la mécanique par"},{"type":"p","text":"cette façon ignoble de gagner sa vie."},{"type":"p","text":"Mi Hacker mi mécanicien, lenny fit rapidement fortune bien que tout s’effondra avec les crises,"},{"type":"p","text":"survivant comme il pouvait en bricolant et réparant des appareils ménagers et groupes électrogènes."},{"type":"p","text":"Avec le boom technologique, lenny tenta d’intégrer de grandes corporations avec ses diplômes en"},{"type":"p","text":"vérité assez prestigieux bien qu’il révisa et les passa à domicile, mais son logifate était absolument"},{"type":"p","text":"hors normes"},{"type":"p","text":"Lenny demeura caché et continua de se mettre à jour, on lui doit énormément de créations chez les"},{"type":"p","text":"crawlers, bien qu’on ne le connaisse pas, refusant d’être vu physiquement, très complexé."},{"type":"p","text":"Il a rencontré Tia REYNOLDS assez peu de temps après son emménagement à Los Angeles, il serait"},{"type":"p","text":"son mécanicien attitré pour l’entretien et l’amélioration de ses armes."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-dushane-murray","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Dushane MURRAY","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs","Cyppers"],"pnj":{"completeness":"detailed","real_name":"Dushane MURRAY","identity_keys":["Dushane MURRAY","Le dealer de titane"],"statut":"Cyppers","organisation":"Meditechs","age":"29 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Dushane MURRAY"],["Alias / désignation","Le dealer de titane"],["Âge","29 ans"],["Affiliations","Cyppers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Meditechs"],["Sous-type","Cyppers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Kiandra Price"],["Bronte Houston"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Le commerce des augmentations de seconde main est aussi rentable que difficile, les mécaniciens"},{"type":"p","text":"capables de les greffer sans mal ni conséquences sont peu nombreux."},{"type":"p","text":"Avec les grands murs et bâtiments condamnés que le LAUS a instauré pour segmenter la ville de Los"},{"type":"p","text":"Angeles, certains quartiers ont été étranglés, abandonnés et totalement isolés, pour se doter en"},{"type":"p","text":"améliorations de toutes sortes, les plus défavorisés furent amenés à renforcer la place des gangs, les"},{"type":"p","text":"armer et intégrer leurs rangs."},{"type":"p","text":"Dushane prit assez tôt la tête d’un petit gang, les « Ivory Lion », dont les membres étaient"},{"type":"p","text":"reconnaissables à leur crête blanche ou beige. Criminel endurci, il assuma chaque meurtre, chaque"},{"type":"p","text":"vol et chaque incendie en se défendant d’être le protecteur de sa rue."},{"type":"p","text":"Durant un affrontement avec des rivaux, il prit dix balles dans le corps, dont deux dans le dos qui le"},{"type":"p","text":"paralysèrent, incapable de marcher et très affaibli, n’ayant aucune aide ni soin spécifique pour"},{"type":"p","text":"récupérer, il frôla la mort, abandonné par sa sœur et incapable de se nourrir, sa survie passa par la"},{"type":"p","text":"venue providentielle de kiandra Price, une prostituée et cheffe d’un gang féminin, laquelle venait"},{"type":"p","text":"racketter Chaybree, la sœur de Dushane."},{"type":"p","text":"Au lieu de le laisser crever, elle le sauva pour faire pression sur Chaybree. Bien qu’elle l’eût laisser"},{"type":"p","text":"crever par manque de fric, Dushane sauva toutefois sa sœur, prenant sa dette en échange d’une"},{"type":"p","text":"« Tech-chine », une échine mécanique afin de remarcher. Ainsi débuta sa carrière de Crawler,"},{"type":"p","text":"Dushane remboursant Kiandra et apprit à la dure à réparer, entretenir et améliorer son équipement"},{"type":"p","text":"vital, il s’occupa de son quartier, dotant ses camarades de misère d’augmentations, faute de vrais"},{"type":"p","text":"soins, les « Ivory Lion » reprirent du poil de la bête."},{"type":"p","text":"Il s’allia aux Crips avec notamment Bronte Houston et est désormais leur principal « mec. »,"},{"type":"p","text":"cependant, il n’a aucun scrupule à équiper des bloods tant que cela ne se sait pas."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-narako-austin","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Narako AUSTIN","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs","Venomers"],"pnj":{"completeness":"detailed","real_name":"Narako AUSTIN","identity_keys":["Narako AUSTIN","La pyrotechnicienne"],"statut":"Meditechs","organisation":"Meditechs","age":"42 ans","nationalite":"Américano-japonaise"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Narako AUSTIN"],["Alias / désignation","La pyrotechnicienne"],["Âge","42 ans"],["Affiliations","Meditechs"],["Nationalité d’origine","Américano-japonaise"],["Famille Crawler","Meditechs"],["Sous-type","Venomers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Malgré son visage assez jeune, Narako est née en 1993, à los Angeles, d’une mère japonaise et d’un"},{"type":"p","text":"père américain."},{"type":"p","text":"Elle a grandi entre Tokyo et sa ville natale, allant et venant sans cesse, totalement bilingue c’est"},{"type":"p","text":"toutefois la Corée du sud qui la passionna le plus durant sa jeunesse."},{"type":"p","text":"Particulièrement douée dans ses études d’ingénieur, elle resta dans la compagnie d’armement"},{"type":"p","text":"« Moga’ei » jusqu’à la quasi-faillite de cette entreprise japonaise pendant la guerre."},{"type":"p","text":"Loin de vouloir rester sur un champ de bataille, elle retourna aux Etats-Unis pour se mettre à l’abris"},{"type":"p","text":"et resta ingénieur dans une grosse boite de production jusqu’en 2030."},{"type":"p","text":"Pendant 8 ans, elle vécut assez correctement malgré les crises économiques et les catastrophes"},{"type":"p","text":"écologiques, mariée à Sung-chin RANG, un émigré coréen, elle avait deux enfants, Kyung et Kevin,"},{"type":"p","text":"âgés de 7 et 5 ans, une vie normale."},{"type":"p","text":"En 2030 elle cautionna à 100% les nouvelles technologies qui sortaient enfin, ravie de présenter sur"},{"type":"p","text":"plusieurs salons des projets sur lesquels elle avait travaillé. Il y en avait un, toutefois, qu’elle ne vit"},{"type":"p","text":"pas venir et qui l’enthousiasma encore plus que les autres : le Logifate. Quand le conseil"},{"type":"p","text":"d‘administration de Byron industries, où elle était ingénieur, demanda à ses cadres de se soumettre"},{"type":"p","text":"« pour la forme » à l’évaluation, elle fut assez surprise de se retrouver déviante, hors système,"},{"type":"p","text":"« parasite » elle était plus que ça, elle était classée « dangereuse » et fut virée sur le champ."},{"type":"p","text":"Son mari la quitta en quelques semaines, les médias ne cessant d’expliquer les dangers à côtoyer un"},{"type":"p","text":"logifate hors système, elle ne se laissa pas faire mais les juges ne lui donnèrent absolument pas"},{"type":"p","text":"raison quant à la garde de ses enfants, condamnée à ne pas avoir de travail décent, elle ne pouvait"},{"type":"p","text":"les élever."},{"type":"p","text":"On aurait pu imaginer qu’une petite ingénieure jetée dans les bas quartiers du jour au lendemain"},{"type":"p","text":"allait mal finir, cependant le logifate est un ensemble d’IA puissantes et quand Narako fut désignée"},{"type":"p","text":"comme « dangereuse », c’est qu’en effet, elle pouvait le devenir, et le devint très vite."},{"type":"p","text":"Travaillant comme meditech, elle se montra d’une violence et d’une ingéniosité sadique quant à la"},{"type":"p","text":"pratique du sabotage et la création de bombes, se faisant vite un nom chez les « Cyppers »."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-aisha-white","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Aisha WHITE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs","Venomers"],"pnj":{"completeness":"detailed","real_name":"Aisha WHITE","identity_keys":["Aisha WHITE","La création parfaite"],"statut":"Venomers","organisation":"Meditechs","age":"25 ans","nationalite":"Américano-russe"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Aisha WHITE"],["Alias / désignation","La création parfaite"],["Âge","25 ans"],["Affiliations","Venomers"],["Nationalité d’origine","Américano-russe"],["Famille Crawler","Meditechs"],["Sous-type","Venomers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Aisha serait née en 2010, elle serait la fille illégitime du professeur Zarimoff, un monument chez les"},{"type":"p","text":"scientifiques russes que les Nord-coréens auraient capturé avant la guerre."},{"type":"p","text":"Elle a une beauté surnaturelle et est une implacable meditech. Elle ne se concentre absolument pas"},{"type":"p","text":"sur les soins et les réparations, du moins pas pour ceux des autres personnes."},{"type":"p","text":"Armée d’une immense « katanaçonneuse » dont la partie la plus extrême est un mono-filament, c’est"},{"type":"p","text":"un « venomer » des plus redouté, en effet, elle est capable d’utiliser des capsules électrochimiques"},{"type":"p","text":"pour altérer le génome de ses cibles quand elle ne les tranche pas avec son arme."},{"type":"p","text":"livre pas trop dessus, comme il s’agit d’une méditech elle a une connaissance surprenante dans le"},{"type":"p","text":"corps humain et la mécanique, même si elle préfère utiliser ses savoirs pour tuer ou immobiliser."},{"type":"p","text":"Elle reste tout à fait apte à prodiguer plus que des soins d’urgence à ceux et celles qu’elle pourrait"},{"type":"p","text":"Aisha est une crawler assez riche, elle posséderait une maison assez grande quelque part en"},{"type":"p","text":"Californie mais l’adresse est inconnue afin de protéger sa vie privée."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"Aisha est parfois à peine humaine dans ses réactions, on ignore quelle a été son enfance, et elle ne se"},{"type":"p","text":"sauver mais la rumeur dit qu’elle ne le fait que contre de l’argent."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-arnstein-gill","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Arnstein GILL","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs","Venomers"],"pnj":{"completeness":"detailed","real_name":"Arnstein GILL","identity_keys":["Arnstein GILL","Le magicien des chairs"],"statut":"Venomers","organisation":"Meditechs","age":"54 ans","nationalite":"Norvégienne"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Arnstein GILL"],["Alias / désignation","Le magicien des chairs"],["Âge","54 ans"],["Affiliations","Venomers"],["Nationalité d’origine","Norvégienne"],["Famille Crawler","Meditechs"],["Sous-type","Venomers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Arnstein était un chimiste et un généticien, une pointure dans le domaine médicale, évidemment,"},{"type":"p","text":"peu connu du grand public, c’est progressivement qu’il a gagné les plateaux télévision avant la crise"},{"type":"p","text":"du Covid."},{"type":"p","text":"Eclipsé par des collègues plus pertinents face aux discussions sur la pandémie, il a mal digéré de"},{"type":"p","text":"retomber dans l’anonymat, il ne fit, pas partie de l’équipe de Leslie Wright pendant la guerre, se"},{"type":"p","text":"concentrant sur sa boite privée pharmaceutique qui, hélas pour lui fit faillite pendant la grande"},{"type":"p","text":"dépression."},{"type":"p","text":"Quittant sa Norvège pour New-York, il fut témoin de l’appauvrissement général, très fort aux Etats￾Unis mais surtout de la dégradation totale du système politique. Par 12 fois il retenta de lancer des"},{"type":"p","text":"boites et à chaque fois il fit faillite, s’éclipsant dans un autre état, le FBI n’ayant aucun budget, le"},{"type":"p","text":"laissant fuir."},{"type":"p","text":"Pendant l’essor des corporations, il fonda « Biognar » et retrouva une fortune colossale en quelques"},{"type":"p","text":"mois, produisant des N-sta, ces neuro-stabilisateurs essentiel pour posséder des augmentations"},{"type":"p","text":"mécaniques. Il les faisait faire au Mexique dans les maquiladoras, à un prix monstrueusement bas."},{"type":"p","text":"Toutefois la guerre du Mexique débuta, les Cartels affrontant les corporations."},{"type":"p","text":"GILL ne voyait pas assez loin, refusant de défendre des industries, pour lui, dépenser de l’argent"},{"type":"p","text":"inutilement briserait la rentabilité monstrueuse, préférant reconstruire plus loin, une grave erreur,"},{"type":"p","text":"très vite, il n’eut plus aucune main d’œuvre, ne put rien reconstruire ni rien produire, Sunways"},{"type":"p","text":"l’achevant sur le plan économique."},{"type":"p","text":"Jeté dans l’ombre encore une fois, il devint le médecin des mafieux et se dévoua aux Triades et leur"},{"type":"p","text":"marché écœurant de la prostitution s’occupant de fournir drogues, somnifères et dopants."},{"type":"p","text":"Malgré tout assez connu dans le milieu pharmaceutique et médical, GILL possède un très puissant"},{"type":"p","text":"réseau de médecins et scientifiques qu’il fait chanter pour être approvisionner, le plaçant en tête de"},{"type":"p","text":"liste des « médicrawlers », bien que ce soient les mafias qui gèrent ses produits."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-calvin-barron","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Calvin BARRON","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Calvin BARRON","identity_keys":["Calvin BARRON","Le pillard"],"statut":"Gundrivers","organisation":"Gundrivers","age":"47 ans","nationalite":"américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Calvin BARRON"],["Alias / désignation","Le pillard"],["Âge","47 ans"],["Affiliations","Gundrivers"],["Nationalité d’origine","américaine"],["Famille Crawler","Gundrivers"],["Sous-type","Gundrivers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Veronica Silver"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Parmi les clubs de motard errant sur les routes désertes de Californie le Cruisers MC est un des clubs"},{"type":"p","text":"les plus violents sévissant."},{"type":"p","text":"Rivaux des Hell Angels, ils s’appuient sur un vaste réseau de distribution de contrebande, notamment"},{"type":"p","text":"via les gangs « Reapers ». Il possède une centaine de chapitres en Californie."},{"type":"p","text":"Bien que les clubs de motards puisent pas mal de leurs origines et de leurs alliances avec les"},{"type":"p","text":"mouvements neonazi, on ne leur attribue pratiquement pas de crimes raciaux, c’est probablement"},{"type":"p","text":"pour cela qu’ils n’ont pas de mal à collaborer avec les Grim Reapers de Luther Pierce ou des gangs"},{"type":"p","text":"mexicains, afro-américains et les mafias."},{"type":"p","text":"Calvin BARRON est le président actuel, au tournant des années 2020, on ne lui connaissait pas grand￾chose, un trafiquant occasionnel d’armes ou passeur d’immigrants mexicains, avec la grande crise, il"},{"type":"p","text":"s’est montré redoutable, son club s’est diversifié."},{"type":"p","text":"Les motards ont dominé les déserts américains et ont contribué à chasser les habitants de petites"},{"type":"p","text":"villes, se faisant payer par les corporations ou les grosses municipalités qui profitaient de l’exode"},{"type":"p","text":"rurale."},{"type":"p","text":"En dehors de LA, il règne sur pas mal de routes, et la menace est réelle quant à être attaqué par un"},{"type":"p","text":"groupe de motards quand on ne paye pas les « douanes en cuir »."},{"type":"p","text":"Etant extrêmement mobiles le LAUS a énormément de mal à arrêter Barron, ses associés et ses"},{"type":"p","text":"rivaux."},{"type":"p","text":"Chez les crawlers, ces motards sont de véritables durs, ils ont beau être souvent peu augmentés, les"},{"type":"p","text":"« receleurs » de type motards sont des brutes, de véritables hordes de pillards sur leurs chevaux"},{"type":"p","text":"modernes."},{"type":"p","text":"Tout ce qui sort des grandes villes par un autre moyen que ceux aériens ou les trains à ultravitesse"},{"type":"p","text":"finira toujours par se faire attaquer par des motards et ira dans leurs hangars."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-arthur-bartram","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Arthur BARTRAM","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers"],"pnj":{"completeness":"detailed","real_name":"Arthur BARTRAM","identity_keys":["Arthur BARTRAM","Evil Odin"],"statut":"Gundrivers","organisation":"Gundrivers","age":"52 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Arthur BARTRAM"],["Alias / désignation","Evil Odin"],["Âge","52 ans"],["Affiliations","Gundrivers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Gundrivers"],["Sous-type","Gundrivers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Frederic Jackelston"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Le plus célèbre des gangs de motard est celui des Hell Angels et fut fondé en 1948."},{"type":"p","text":"C’est le plus iconique des clubs de motards mais aussi le plus connu pour ses activités criminelles."},{"type":"p","text":"Le contexte de crise, de guerre et de grand chamboulement technologique a énormément changé la"},{"type":"p","text":"vie des bikers, à l’instar des Cruisers, les hells angels ont fortement aidé à la fuite des villages, pillant"},{"type":"p","text":"et tuant."},{"type":"p","text":"On trouve à la tête du plus influent des chapitres Arthur BARTRAM."},{"type":"p","text":"Les hell Angels ont changé de tactique une fois la désertification et l’exode rural accentué, fortifiant"},{"type":"p","text":"des villages et non plus en tant que pillards mais en tant que gardiens, assurèrent les points de"},{"type":"p","text":"passages aux routiers, les défendant contre une rémunération pouvant être pécuniaire aussi bien"},{"type":"p","text":"qu’une partie des cargaisons."},{"type":"p","text":"Surnommé « Odin » à cause de son œil en moins, Arthur est un monstre n’hésitant pas à réduire les"},{"type":"p","text":"gens en esclavage tous ceux qui s’aventurent sur « ses » routes."},{"type":"p","text":"S’il est totalement assimilé à la pègre par la Police, il s’avère très souvent contacté pour des missions"},{"type":"p","text":"de protection de convois, de marchandises ou d’assassinats."},{"type":"p","text":"Les Hells Angels sont plus souvent des combattants que des transporteurs, ils ont les armes, les"},{"type":"p","text":"effectifs, alors ils s’imposent comme une des armées mercenaires les plus réputées et bien que les"},{"type":"p","text":"corporations de sécurité n’apprécient qu’assez peu la comparaison on trouve presque autant"},{"type":"p","text":"d’anciens militaires chez ces motards que dans leurs rangs."},{"type":"p","text":"D’un point de vue personnel, BARTRAM est un monstre du combat, augmenté pour posséder une"},{"type":"p","text":"force colossale, l’énorme biker peut briser une voiture de ses poings et sortir des lames tel Wolverine"},{"type":"p","text":"qui lui servent à découper des portes blindées ou des bikers ennemis. Piètre tireur en revanche, il"},{"type":"p","text":"préfère le corps à corps à une époque ne s’y prêtant pas, ayant déjà pris plus de soixante balles dans"},{"type":"p","text":"le corps pour obtenir la tête d’un type."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-kashrim-el-khayat","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kashrim el KHAYAT","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers","Necropunks"],"pnj":{"completeness":"detailed","real_name":"Kashrim el KHAYAT","identity_keys":["Kashrim el KHAYAT","Le prince d’Iranie"],"statut":"Gundrivers","organisation":"Gundrivers","age":"31 ans","nationalite":"Iran"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kashrim el KHAYAT"],["Alias / désignation","Le prince d’Iranie"],["Âge","31 ans"],["Affiliations","Gundrivers"],["Nationalité d’origine","Iran"],["Famille Crawler","Gundrivers"],["Sous-type","Necropunks"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Saskia"],["Farah el Arshad"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Les grandes crises écologiques et financières ont mené à la désertification et l’exode de nombreuses"},{"type":"p","text":"régions du monde, ce ne fut pas le cas de l’iran qui continua de se développer."},{"type":"p","text":"Avec l’essor de nouvelles technologies, on découvrit des ressources essentielles plus profondément"},{"type":"p","text":"dans les sols de l’Iran les grosses familles investissant firent une fortune plus colossale que les princes"},{"type":"p","text":"du pétrole."},{"type":"p","text":"Les corporations jouèrent le jeu des rivalités entre ces grandes familles et finalement l’Iran devint"},{"type":"p","text":"une terre corporatiste aisément, à l’exception d’un petit territoire nommée « Iranie », possédé par la"},{"type":"p","text":"famille el Khayat,une famille de diplomates à la base."},{"type":"p","text":"c’est cette famille qui fut la grande gagnante de ces rivalités et devint une famille princière d’une"},{"type":"p","text":"richesse colossale, elle déclara même « l’Iranie » comme pays indépendant. L’incroyable armée"},{"type":"p","text":"« Iraniienne » calma les corporations quant à l’idée de disputer aux Khayat leurs gisements si"},{"type":"p","text":"abondants."},{"type":"p","text":"Kashrim, un des princes a toujours été amateur des Etats-Unis, y ayant étudié, sa grande passion,"},{"type":"p","text":"après les femmes était les voitures et motos, tout ce qui fait de la vitesse d’ailleurs."},{"type":"p","text":"C’est ainsi qu’il se posa avec sa fortune à la tête d’un empire de courses illégales, lui-même très doué"},{"type":"p","text":"pour le pilotage en neurodrive aussi bien que la mécanique. Il rencontra la directrice d’Eversor"},{"type":"p","text":"corporation, Saskia, lors d’une course, qu’il n’arriva pas à remporter."},{"type":"p","text":"Il n’a absolument rien à foutre des lois de la grande Californie, pour lui, l’argent est la seule loi qu’il"},{"type":"p","text":"écoute, aussi, ce type n’étant pas vraiment crawler pas vraiment corporatiste ni vraiment autre"},{"type":"p","text":"chose pour autant se retrouve régulièrement devant des juges californiens, sans jamais être vraiment"},{"type":"p","text":"condamné, dit-on que Farah el Arshad, la juge suprême et lui se connaissant, elle influerait sur les"},{"type":"p","text":"verdicts."},{"type":"p","text":"Chez les Crawlers, ce riche milliardaire est généreux avec ceux amicaux, sans pitié avec ceux qui"},{"type":"p","text":"échouent ou ne le respectent pas, ce qui pour lui est synonyme. Ne disposant pas d’industrie, il"},{"type":"p","text":"rachète aux corporation des tonnes de matériel qu’il revend plus cher une fois modifié par ses"},{"type":"p","text":"équipes de mécaniciens, il terrifie certains directeurs de corporations car les contrats avec lui sont"},{"type":"p","text":"très juteux voir impossibles à refuser mais derrière il perce les brevets pour les revendre aux"},{"type":"p","text":"concurrents, ce qui réduit la rentabilité sur le long terme drastiquement."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-kendasha-roberts","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kendasha ROBERTS","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers","Necropunks"],"pnj":{"completeness":"detailed","real_name":"Kendasha ROBERTS","identity_keys":["Kendasha ROBERTS","La goule dorée."],"statut":"Necropunks","organisation":"Gundrivers","age":"28 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kendasha ROBERTS"],["Alias / désignation","La goule dorée."],["Âge","28 ans"],["Affiliations","Necropunks"],["Nationalité d’origine","Américaine"],["Famille Crawler","Gundrivers"],["Sous-type","Necropunks"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Les charognards sont détestés et détestables, entre tous, pourtant, la plus célèbre est Kendasha"},{"type":"p","text":"ROBERTS et elle est aussi admirée qu’appréciée."},{"type":"p","text":"Kendasha possède des équipes de crawlers ciblant des augmentations rares, d’autres crawlers la"},{"type":"p","text":"payent pour avoir des demandent précises et elle s’occupe de traquer des individus possédant à peu"},{"type":"p","text":"près la demande."},{"type":"p","text":"Elle a des yeux partout dans les corporations en produisant et celles les installant mais elle a surtout"},{"type":"p","text":"un très gros réseau de légistes et d’infirmiers à sa botte, dépeçant sur les accidentés les yeux ou"},{"type":"p","text":"mains mécaniques."},{"type":"p","text":"Riche héritière du grand directeur de Kingstartech, elle n’imaginait pas basculer entre 2033 et 2034"},{"type":"p","text":"du statut de princesse à celui de vagabonde quand Byron Industries corporation a explosé cette"},{"type":"p","text":"compagnie qui était au sein de la corporation."},{"type":"p","text":"Désormais, elle ramasse les morceaux de la compagnie pour se venger à sa manière, récupérant les"},{"type":"p","text":"cadres par du chantage ou autre afin de les faire bosser dans son réseau de « charognards »,"},{"type":"p","text":"grignotant le rendement de Byron Corporation ainsi."},{"type":"p","text":"Réputée élégante et maniérée, elle s’est très bien adaptée à la vie dans les quartiers abandonnés et"},{"type":"p","text":"de temps en temps joint les festivités corporatives."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-yan-xiao","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Yan XIAO","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers","Necropunks"],"pnj":{"completeness":"detailed","real_name":"Yan XIAO","identity_keys":["Yan XIAO","Le vautour chinois"],"statut":"Necropunks","organisation":"Gundrivers","age":"22 ans","nationalite":"chinoise"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Yan XIAO"],["Alias / désignation","Le vautour chinois"],["Âge","22 ans"],["Affiliations","Necropunks"],["Nationalité d’origine","chinoise"],["Famille Crawler","Gundrivers"],["Sous-type","Necropunks"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Après la grande guerre, les crises économiques auraient pu servir les intérêts de la Chine, un des pays"},{"type":"p","text":"les mieux équipé industriellement, à même de se redresser plus vite, mais il n’en fut rien puisque"},{"type":"p","text":"pas seulement en Californie mais partout dans le monde des catastrophes écologiques survinrent,"},{"type":"p","text":"face à ces atroces évènements, ce ne sont pas des aides humanitaires que reçut la Chine mais des"},{"type":"p","text":"sanctions économiques, lui imputant le changement climatique en raison de son manque de"},{"type":"p","text":"participation à l’effort pour y lutter."},{"type":"p","text":"C’est dans une Chine dévastée, polluée et misérable, abandonnée aux corporations qui émergeaient"},{"type":"p","text":"que Yan a grandi."},{"type":"p","text":"L’orphelin était un « guai dao », un pillard envoyé sur les zones interdites de la guerre de Corée, pour"},{"type":"p","text":"piller les épaves de véhicules militaires."},{"type":"p","text":"Il organisa les ramassages et défendait avec une agressivité rare les autres gamins, dès ses 17 ans, il"},{"type":"p","text":"amassa assez de fric, d’armes et de réputation pour traiter avec les Triades. Tout aurait dû se finir là,"},{"type":"p","text":"le jour où un mafieux rata sa tête en lui tirant dessus. Mais au contraire, sa survie le marqua assez"},{"type":"p","text":"pour le traumatiser, pas en lui insufflant de la peur mais de la colère."},{"type":"p","text":"En Californie, Yan s’implanta vite, véritable vautour passant avec ses équipes après les mafieux ou les"},{"type":"p","text":"affrontements corporatistes."},{"type":"p","text":"Il est en grande rivalité avec Kendasha ROBERTS et il est aussi imprévisible et sanguinaire qu’elle est"},{"type":"p","text":"calme et méticuleuse. Malgré des apparences de gamin immature, c’est probablement un génie aux"},{"type":"p","text":"tendances psychopathes."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-tuuwa-kolenya","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Tuuwa KOLENYA","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers","Neoslavers"],"pnj":{"completeness":"detailed","real_name":"Tuuwa KOLENYA","identity_keys":["Tuuwa KOLENYA"],"statut":"Necropunks","organisation":"Gundrivers","age":"21 ans","nationalite":"américaine (cherokee)"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Tuuwa KOLENYA"],["Âge","21 ans"],["Affiliations","Necropunks"],["Nationalité d’origine","américaine (cherokee)"],["Famille Crawler","Gundrivers"],["Sous-type","Neoslavers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Après la création de la grande réserve, malgré l’immense richesse de Tokala, la gouverneure de cette"},{"type":"p","text":"dernière, énormément d’amérindiens n’ont pas spécialement vu leurs conditions de vie s’améliorer,"},{"type":"p","text":"ils n’ont été qu’un peu plus déportés, non plus par des blancs mais une des leurs."},{"type":"p","text":"A l’instar de l’insurrection civile, il existe des amérindiens de la grande réserve voulant s’armer pour"},{"type":"p","text":"ne pas dépendre de la tala corporation, pour eux, la grande réserve est un pays corporatiste où"},{"type":"p","text":"Tokala est leur maitresse absolue et ils s’y refusent."},{"type":"p","text":"Par esprit de liberté et de traditions, plusieurs factions cherchent donc à s’équiper, s’éloignant de"},{"type":"p","text":"leurs traditions, se sacrifiant en s’augmentant, seule alternative à la soumission."},{"type":"p","text":"Koyah en était un des plus illustres l’instigateurs, mais tué assez vite, c’est sa fille, Tuuwa qui a repris"},{"type":"p","text":"la tête de ce mouvement."},{"type":"p","text":"Concrètement, c’est juste une « charognard » allant et venant de Las Vegas à la grande réserve,"},{"type":"p","text":"pillant précisément véhicules, armes et augmentations nécessaires à équiper ses troupes. On la"},{"type":"p","text":"décrit souvent avec un visage angélique et innocent qui cache les méthodes du corbeau et du coyote."},{"type":"p","text":"Régulièrement en conflit avec les troupes armées de la Tala corporation, elle semble soit ne pas"},{"type":"p","text":"représenter encore une réelle menace soit avoir une relative tolérance de la part de la pourtant très"},{"type":"p","text":"sévère Tokala qui n’a, actuellement, jamais pris de réelle mesure pour anéantir ce mouvement."},{"type":"p","text":"Tuuwa est assez jeune néanmoins, c’est possiblement une de ses plus grandes faiblesses puisqu’à sa"},{"type":"p","text":"prise de pouvoir, après la mort de son père, énormément de partisans ont fini par se raviser et"},{"type":"p","text":"attendre."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-todd-larsen","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Todd LARSEN","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers","Neoslavers"],"pnj":{"completeness":"detailed","real_name":"Todd LARSEN","identity_keys":["Todd LARSEN","Black Procurer"],"statut":"Mandealers","organisation":"Gundrivers","age":"44 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Todd LARSEN"],["Alias / désignation","Black Procurer"],["Âge","44 ans"],["Affiliations","Mandealers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Gundrivers"],["Sous-type","Neoslavers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Dina Page"],["Robert HAMILTON"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Todd est essentiellement connu par la police pour être issu de mouvances Neonazies."},{"type":"p","text":"Plusieurs fois condamné pour violence raciste et esclavage moderne, Todd est une ordure qui se"},{"type":"p","text":"servait de la drogue et de la pauvreté des bas quartiers de Los Angeles pour forcer des afro￾américains à le servir."},{"type":"p","text":"aurait même été proche du maire actuel, Robert HAMILTON et aurait connu Dina PAGE dans sa"},{"type":"p","text":"jeunesse."},{"type":"p","text":"Comme beaucoup de neonazi, il participa à la guerre, mais il quitta vite l’armée pour joindre une"},{"type":"p","text":"milice, pas fou, refusant de crever pour la nation."},{"type":"p","text":"De retour au pays assez vite, soi-disant blessé, on l’accusa de n’avoir aucune forme de fierté, d’être"},{"type":"p","text":"loin des valeurs racistes et patriotes qu’il semblait défendre et se fit progressivement détesté par une"},{"type":"p","text":"part de ses anciens « frères », cela ne l’affectant pas néanmoins, Todd s’en foutant royalement des"},{"type":"p","text":"conneries racistes en vérité, ne jouant dessus que pour le fric qu’il se faisait."},{"type":"p","text":"Avec l’essor des mafieux, néanmoins, son réseau de prostitution se fit attaquer régulièrement et face"},{"type":"p","text":"à Drasko VLADIC, Todd fut très vite obligé de déposer les armes, la mafia russe lui arrachant des"},{"type":"p","text":"doigts son commerce."},{"type":"p","text":"LARSEN continua ses activités, s’il est considéré comme un criminel recherché par la police, c’est"},{"type":"p","text":"surtout un crawler à la tête d’un puissant réseau d’anciens suprématistes blancs comprenant des"},{"type":"p","text":"tolards, des militaires, corporatistes, motards et autres crawlers."},{"type":"p","text":"il ne se limite pas au commerce d’humains mais d’armes et de pièces d’augmentations, Todd a"},{"type":"p","text":"toujours ce qu’il faut si on a de quoi payer."},{"type":"p","text":"Un de ses commerces reste la traite d’humains, les technologies désormais permettent le lavage de"},{"type":"p","text":"cerveau mieux que jamais…"}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"Ses affaires l’installèrent à la tête d’un réseau aussi immonde que rentable et certains disent qu’il"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-kerlyn-sherres","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kerlyn SHERRES","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers","Neoslavers"],"pnj":{"completeness":"detailed","real_name":"Kerlyn SHERRES","identity_keys":["Kerlyn SHERRES","l’amie des corpos"],"statut":"Mandealers","organisation":"Gundrivers","age":"37 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kerlyn SHERRES"],["Alias / désignation","l’amie des corpos"],["Âge","37 ans"],["Affiliations","Mandealers"],["Nationalité d’origine","Américaine"],["Famille Crawler","Gundrivers"],["Sous-type","Neoslavers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Kerlyn est née en 1998, à Philadephie."},{"type":"p","text":"Elle a toujours eu un excellent relationnel avec les gens mais n’a jamais apprécié étudier ou trop se"},{"type":"p","text":"prendre la tête, tentant des études vaguement en psychologie qu’elle abandonna vite, elle se fit une"},{"type":"p","text":"expérience conséquente en management et fit éditer trois bouquins sur la confiance en soi et son"},{"type":"p","text":"impact sur la réussite sociale et professionnelle. Ecrivaine ayant ses quelques mois de gloire elle"},{"type":"p","text":"retomba vite dans l’anonymat avec la guerre de 2022."},{"type":"p","text":"Folle de réseaux sociaux avant la guerre, elle continua de les utiliser et d’en abuser, rentabilisant son"},{"type":"p","text":"image sous toutes les formes, toutes les plateformes, tous les formats, essayant même de pousser à"},{"type":"p","text":"réaliser un film sur elle-même alors que, concrètement, elle n’était personne."},{"type":"p","text":"Sa mégalomanie la préserva même pendant les temps difficiles, la « Siobhain black » autoproclamée"},{"type":"p","text":"survivant par des dons, des ventes, des services, des conseils, se faisant même pasteure un temps"},{"type":"p","text":"pur avoir plus de légitimité à conseiller."},{"type":"p","text":"Pendant les grandes crises, elle s’acoquina avec les cartels de la drogue au Mexique, montant une"},{"type":"p","text":"boite de recrutement américaine pour faire miroiter aux mexicains un travail « de rêve », rien de plus"},{"type":"p","text":"que trimer dans les maquiladoras en vérité, mais elle était si douée que l’arnaque surprenait les"},{"type":"p","text":"corporations naissantes ayant besoin de cette main- d’œuvre si peu chère payée."},{"type":"p","text":"Ainsi débuta la carrière de Kerlyn comme chien de berger des corporations, allant dans le monde"},{"type":"p","text":"entier récupérer des pauvres émigrés dans les pays en guerre ou instables afin de les ramener sous"},{"type":"p","text":"contrat américains pour mieux les faire trimer en les revendant aux corporations une fois ramenés"},{"type":"p","text":"sur le sol américain, triés et testés au logifate pour ne vendre que les plus adaptés."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-leslie-wright","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Leslie WRIGHT","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Leslie WRIGHT","identity_keys":["Leslie WRIGHT","Déesse de la technologie"],"statut":"Neopunks","organisation":"Neopunks","age":"36 ans","nationalite":"Britannique"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Leslie WRIGHT"],["Alias / désignation","Déesse de la technologie"],["Âge","36 ans"],["Affiliations","Neopunks"],["Nationalité d’origine","Britannique"],["Famille Crawler","Neopunks"],["Sous-type","Neopunks"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Levanah URIEL"],["Damon HARRINGTON"],["Etc."]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Elle est le plus grand génie de la Terre, certains estiment qu’il est impossible de calculer son QI étant"},{"type":"p","text":"donné les méthodes limitantes actuelles."},{"type":"p","text":"Véritable monstre cognitif, elle n’était qu’une petite dernière d’une famille anglaise assez pauvre et"},{"type":"p","text":"s’est vu être demandée dans de nombreuses universités de prestigieuses. Son caractère très rebelle"},{"type":"p","text":"néanmoins la mena à étudier et très vite enseigner aux Etats-Unis plutôt que dans la vieille"},{"type":"p","text":"Angleterre stricte et désuète."},{"type":"p","text":"Fondamentalement punk dans l’âme, elle mena une carrière dans la musique en parallèle de son"},{"type":"p","text":"travail scientifique. Lorsque la guerre a éclaté, elle fut chargée de rehausser le niveau technologique"},{"type":"p","text":"des forces du Pacifique et surpassa les découvertes des Nord-coréens."},{"type":"p","text":"Absolument tous ses travaux furent exploités et firent la richesse des megacorporations. Si Leslie est"},{"type":"p","text":"la mère de la société actuelle en 2035, elle ne la cautionne pas forcément, anti-système depuis"},{"type":"p","text":"toujours, elle s’épanouit au moins autant dans l’univers des quartiers abandonnés, durant de vastes"},{"type":"p","text":"concerts sauvages de neopunk, un style qu’elle incarne à merveille."},{"type":"p","text":"Les neopunks sont avant tout anti-corporatistes, ils expriment leur colère et leur frustration par leurs"},{"type":"p","text":"arts et leur violence, ce sont des créateurs libres avant toute chose, le groupe de Leslie, les"},{"type":"p","text":"« Lightning Shadows » est un exemple parfait de ce qu’ils sont."},{"type":"p","text":"Concerts libres et gratuits, ils défendent avec violence un modèle plus sauvage et pkus instinctif,"},{"type":"p","text":"moins limitant et inutilement normé."},{"type":"p","text":"Le paradoxe de Leslie est qu’elle est régulièrement arrêtée par la police pour bagarre, ivresse,"},{"type":"p","text":"atteinte à la pudeur et bien d’autres délits, parfois même des crimes mais aucun jugement ne tombe"},{"type":"p","text":"jamais, tant le gouvernement que les corporations la rendent intouchable, en outre, elle est assez"},{"type":"p","text":"riche pour payer toute condamnation, bien qu’elle ne le fasse jamais elle-même."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-damon-harrington","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Damon HARRINGTON","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks"],"pnj":{"completeness":"detailed","real_name":"Damon HARRINGTON","identity_keys":["Damon HARRINGTON","Hadès"],"statut":"Neopunks","organisation":"Neopunks","age":"?? ans","nationalite":"???"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Damon HARRINGTON"],["Alias / désignation","Hadès"],["Âge","?? ans"],["Affiliations","Neopunks"],["Nationalité d’origine","???"],["Famille Crawler","Neopunks"],["Sous-type","Neopunks"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Leslie Wright"],["Marielle et Darielle"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Damon Harrington est une énigme vivante."},{"type":"p","text":"On ne sait rien sur lui ni où il est né, ni quand, on le suppose être un homme mais même ça rien n’est"},{"type":"p","text":"sûr."},{"type":"p","text":"On le reconnait immédiatement sa tête entièrement tatouée telle un crane et sa crète de couleur"},{"type":"p","text":"vive, qu’il assortit à son grand manteau, les deux pouvant changer de couleur et de motifs à sa guise."},{"type":"p","text":"Il porte éternellement des lunettes opaques et sa voix est clairement modifiée et altérée pour"},{"type":"p","text":"paraitre plus rauque et grave."},{"type":"p","text":"Il se fait surnommer « hadès » au sein des neopunks et il est presque toujours celui qui organise les"},{"type":"p","text":"grandes manifestations et rassemblements de musiciens underground."},{"type":"p","text":"DJ reconnu, il semble savoir jouer de tous les instruments et être un maître du cryptage, seule Leslie"},{"type":"p","text":"Wright allant plus loin dans la complexité de ses musiques quant à leur caractère codé."},{"type":"p","text":"scientifique de Leslie qui aurait été défiguré pendant la guerre et aurait été déclaré mort."},{"type":"p","text":"D’autres disent qu’il est le premier robot à totalement penser comme un humain, qu’il est la création"},{"type":"p","text":"de Leslie Wright et qui, comme elle, est totalement antisystème."},{"type":"p","text":"D’autres disent qu’il s’agit d’une femme, somptueuse, cachant sa beauté sous cette apparence"},{"type":"p","text":"vaguement masculine, et qu’elle est probablement riche, donc forcément Siobhain nic Siridean en"},{"type":"p","text":"personne, maitrisant ainsi toutes les formes d’arts sous sa coupe dans son grand dessein de"},{"type":"p","text":"domination…"},{"type":"p","text":"et utiliserait les neopunk pour se venger d’une offense virtuelle."},{"type":"p","text":"Damon est un neopunk assez pacifique, il ne frappe jamais bien que ses paroles soient violentes elles,"},{"type":"p","text":"serait extrêmement faible ou extrêmement fort. Malgré ça, il est incontournable et extrêmement"},{"type":"p","text":"respecté, peu de neopunk acceptent qu’on le dénigre sans s’en agacer."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"Les rumeurs sont nombreuses, certains disent qu’il s’agit d’un expert en chiffrement de l’équipe"},{"type":"p","text":"Une dernière rumeur fait état d’un fils ainé d’un corporatiste qui serait en rébellion contre son père"},{"type":"p","text":"c’est ce refus à la violence physique qui aliment énormément de rumeurs à son sujet, comme quoi il"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-darielle-power","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Darielle POWER","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Darielle POWER","identity_keys":["Darielle POWER","Meneuse des Void"],"statut":"Neopunks","organisation":"Neopunks","age":"25 ans","nationalite":"américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Darielle POWER"],["Alias / désignation","Meneuse des Void"],["Âge","25 ans"],["Affiliations","Neopunks"],["Nationalité d’origine","américaine"],["Famille Crawler","Neopunks"],["Sous-type","Freerunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Les jumelles Darielle et Marielle sont deux enfants terribles de la MAP."},{"type":"p","text":"Ces deux beautés sont possiblement sur un pied d’égalité avec Leslie Wright sur le plan de la"},{"type":"p","text":"musique."},{"type":"p","text":"Influentes et redoutables, qu’il s’agisse du groupe the Void ou Darkness, leurs groupes respectifs, les"},{"type":"p","text":"neopunks sont en transe dès qu’ils écoutent la moindre note en provenant."},{"type":"p","text":"Chacune a son propre style néanmoins et Darielle, des deux, semble la plus nihiliste."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-ryan-rowe","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ryan ROWE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Ryan ROWE","identity_keys":["Ryan ROWE","Un chef de l’insurrection."],"statut":"Freerunners","organisation":"Neopunks","age":"42 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ryan ROWE"],["Alias / désignation","Un chef de l’insurrection."],["Âge","42 ans"],["Affiliations","Freerunners"],["Nationalité d’origine","Américaine"],["Famille Crawler","Neopunks"],["Sous-type","Freerunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Phoebe Edgar"],["Saskia"],["Franklin Bentley"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Quand aux Etats-Unis, on voit des enfants crever de faim dans les rues, des cadavres et des déchets"},{"type":"p","text":"pourrir sans jamais être ramassés, qu’on voit des corporations devenir de plus en plus riche et de"},{"type":"p","text":"politiciens venir faire voter dans ces mêmes rues leurs citoyens… Il y a un moment où presque"},{"type":"p","text":"n’importe qui n’en peut plus, ce fut le cas de Ryan ROWE."},{"type":"p","text":"Cet ancien membre du SWAT à Los Angeles avait été viré pour violences aggravées, mais lui savait"},{"type":"p","text":"que c’étaient des restrictions budgétaires, le maire Hamilton complotant avec les corporations, on le"},{"type":"p","text":"payait pour faire du LAPD une bande de nazes incapables d’agir, afin de faire mousser les milices"},{"type":"p","text":"corporatistes et ça, ROWE ne le digérait pas."},{"type":"p","text":"Lors d’une émeute, lui qui avait tendance à défendre ses anciens camarades de la police, il décida de"},{"type":"p","text":"bruler des fourgons, réclamant la tête du chef de la police après avoir vu des tirs létaux allonger des"},{"type":"p","text":"étudiants."},{"type":"p","text":"L’insurrection ne commença pas vraiment ce jour-là, elle datait d’avant mais c’est ce jour-là que"},{"type":"p","text":"naquit « Raiser », la figure de proue de ce mouvement, le meilleur combattant des insurgés."},{"type":"p","text":"Continuellement à s’augmenter du mieux qu’il peut, il cherche à détruire le plus d’institutions"},{"type":"p","text":"corrompues et l’influence corporatiste, les égouts, le métro, tous les quartiers abandonnés sont"},{"type":"p","text":"possiblement ses bases temporaires."},{"type":"p","text":"En épousant la cause des insurgés, il n’imaginait pas qu’il aurait toutefois autant de combats à"},{"type":"p","text":"mener, car les gangs et les mafias jouent sur le même terrain de jeu. Tantôt ennemis des"},{"type":"p","text":"corporations, tantôt alliés avec, les membres de la pègre attaquent les insurgés ou les aident selon"},{"type":"p","text":"les intérêts du moment, créant une instabilité constante des alliances."},{"type":"p","text":"ROWE a plusieurs fois explosé, le LAUS utilisant les grands moyens sur lui, il a été reconstruit"},{"type":"p","text":"plusieurs fois, un peu moins humain à chaque fois, il durcit sa vision des choses. Certains craignent"},{"type":"p","text":"qu’il ne soit plus assez sain d’esprit d’ailleurs pour être le leader…"},{"type":"p","text":"ROWE voue une haine profonde au maire et plus encore au chef en second de la Police, Franklin"},{"type":"p","text":"Bentley, qu’il ne peut simplement pas tolérer."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-kristina-ruiz","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Kristina RUIZ","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks","Freerunners"],"pnj":{"completeness":"detailed","real_name":"Kristina RUIZ","identity_keys":["Kristina RUIZ","Un chef de l’insurrection"],"statut":"Freerunners","organisation":"Neopunks","age":"31 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Kristina RUIZ"],["Alias / désignation","Un chef de l’insurrection"],["Âge","31 ans"],["Affiliations","Freerunners"],["Nationalité d’origine","Américaine"],["Famille Crawler","Neopunks"],["Sous-type","Freerunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Raiser"],["Iron Pain"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Kristina Ruiz est une bio-terroriste, anciennement haut placée dans la Corporation Sunways, elle"},{"type":"p","text":"aurait été évincée pour d’obscures raisons et jeux d’influence divers au sein de la corporation."},{"type":"p","text":"Tournant totalement sa veste, elle fonda plusieurs associations caritatives en dénonçant le monopole"},{"type":"p","text":"des soins des corporations biomédicales et les tests sur humains qu’elles pratiquent sans plus aucune"},{"type":"p","text":"forme de contrôle."},{"type":"p","text":"Derrière ces associations se cachaient un vaste réseau de contrebande d’organes artificiels et"},{"type":"p","text":"d’autres produits clonés telle que de la nourriture mais aussi des bactéries et virus. Activement"},{"type":"p","text":"recherchée, elle tiendrait de grands rassemblements illégaux où elle prodiguerait des soins mais"},{"type":"p","text":"confierait aussi des armes biologiques en prévision de nouveaux attentats."},{"type":"p","text":"Kristina est une des trois têtes pensantes de l’insurrection civile, contrairement aux deux autres, elle"},{"type":"p","text":"n’a pas un visage connu des autorités."},{"type":"p","text":"En revanche, elle est celle qui fait le plus de morts quand elle agit, et c’est pourquoi les autorités"},{"type":"p","text":"n’ont pas d’hésitations à la faire rechercher morte ou vive."},{"type":"p","text":"Elle n’a pas le profil des neopunks et insurgés c’est une scientifique à la base, une employée modèle"},{"type":"p","text":"et effacée."},{"type":"p","text":"C’est l’arrêt brutal de son ascension dans la corporation qui l’a totalement rendue dingue en vérité,"},{"type":"p","text":"folle de rage, tout ce qu’elle contenait en elle depuis des années s’est manifestée dans des actes très"},{"type":"p","text":"calculé de terrorisme."},{"type":"p","text":"Les Insurgés la perçoivent comme une femme extrêmement généreuse, attentionnée et pleine"},{"type":"p","text":"d’humanité, la police a profilé une personnalité profondément égocentrique, névrosée et"},{"type":"p","text":"probablement dotée d’un rare sadisme allant avec une lâcheté certaine, l’utilisation de virus et"},{"type":"p","text":"poisons étant le signe d’une nature peureuse."},{"type":"p","text":"probablement d’un autre niveau que celles communément vues sur le marché, ayant pillé Sunways."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"On ignore ses augmentations comme elles sont certainement biologiques, en revanche, elles sont"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-osheena-payne","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Osheena PAYNE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks","Enders"],"pnj":{"completeness":"detailed","real_name":"Osheena PAYNE","identity_keys":["Osheena PAYNE","Iron Pain"],"statut":"freerunners","organisation":"Neopunks","age":"39 ans","nationalite":"américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Osheena PAYNE"],["Alias / désignation","Iron Pain"],["Âge","39 ans"],["Affiliations","freerunners"],["Nationalité d’origine","américaine"],["Famille Crawler","Neopunks"],["Sous-type","Enders"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Ryan ROWE"],["Kristina RUIZ"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Osheena Payne était lieutenant dans l’US Marines Corp, elle était à la guerre contre les coréens du"},{"type":"p","text":"nord et comme beaucoup de vétérans en a été traumatisée."},{"type":"p","text":"Le syndrome post-traumatique de la guerre de 22-28 est surnommé « Overtech syndrome » et"},{"type":"p","text":"consiste à une lourde phobie des technologies nouvelles et des modifications corporelles,"},{"type":"p","text":"particulièrement dans un cadre guerrier, il va souvent de pair avec une incompatibilité neuronale"},{"type":"p","text":"pour les implants."},{"type":"p","text":"Incapable de comprendre l’engouement technologique et ayant perdu toute sa famille en moins de"},{"type":"p","text":"10 ans, Osheena ne trouva pas de travail après la guerre, jugée instable, elle accusa la société d’avoir"},{"type":"p","text":"trop changée en son absence, plusieurs fois condamnée pour violence avant d’être attrapée pour"},{"type":"p","text":"meurtre."},{"type":"p","text":"En prison, elle écrivit un manifeste sur la part absurde des corporations mais aussi des institutions en"},{"type":"p","text":"général sur la société, une œuvre qui prit vite dans les communautés les plus misérables que le"},{"type":"p","text":"système du logifate rejetait de plus en plus. Elle s’échappa lors d’une comparution, décidée à mettre"},{"type":"p","text":"en place les idées qu’elle avait diffusé."},{"type":"p","text":"Extrêmement dangereuse, bien que souffrant d’un « Overtech S. », elle est augmentée militairement,"},{"type":"p","text":"moins que Raiser mais suffisamment pour nécessiter les forces spécialisées de la Police pour la"},{"type":"p","text":"repousser, même seule."},{"type":"p","text":"Son syndrome Overtech devrait lui interdire l’utilisation d’augmentations, son corps et son esprit les"},{"type":"p","text":"rejetant, cependant, Osheena l’a contourné, d’une part par une grande volonté, d’autre part, par des"},{"type":"p","text":"implants neuronaux occultant ses modifications dans son esprit, si cela lui interdit les armes"},{"type":"p","text":"intégrées, toutes les augmentations de capacités « naturelles » semblent compatibles, peu importe"},{"type":"p","text":"leur absurdité en efficacité tant qu’elles ne demandent pas un apprentissage."},{"type":"p","text":"Osheena est réputée aussi cruelle qu’implacable, contrairement à Raiser, elle ne fait pratiquement"},{"type":"p","text":"jamais de prisonniers corporatistes, ne négocie que peu avec les mafias et n’écoute vaguement que"},{"type":"p","text":"les militaires du coté gouvernemental. Au niveau des corporation, les religions et en particulier le"},{"type":"p","text":"Grand Transhumanisme est sa bête noire, tuant systématiquement tout représentant de cette"},{"type":"p","text":"croyance ayant la malchance de croiser son chemin."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-damian-escribano","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Damian ESCRIBANO","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks","Enders"],"pnj":{"completeness":"detailed","real_name":"Damian ESCRIBANO","identity_keys":["Damian ESCRIBANO","Fuel King"],"statut":"Enders","organisation":"Neopunks","age":"44 ans","nationalite":"mexicaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Damian ESCRIBANO"],["Alias / désignation","Fuel King"],["Âge","44 ans"],["Affiliations","Enders"],["Nationalité d’origine","mexicaine"],["Famille Crawler","Neopunks"],["Sous-type","Enders"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["Iron Pain"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Damian est né en 1991, à Guadalajara, au Mexique."},{"type":"p","text":"Ce n’était ni un honnête homme ni une pointure d’un cartel, juste un petit commerçant de souvenirs"},{"type":"p","text":"près de la frontière qui, à l’occasion, faisait passeur ou dealer, arnaqueur et parfois voleur."},{"type":"p","text":"La guerre de 2022, il n’en eut rien à faire, elle n’eut qu’un impact moindre, essentiellement sur la"},{"type":"p","text":"venue des gringos, la guerre entre les corporations puis les corporations avec le gouvernement"},{"type":"p","text":"mexicain le toucha bien plus."},{"type":"p","text":"Il y perdit ses frères, beaucoup d’amis, la guerre allant avec le changement climatique, le désert"},{"type":"p","text":"s’avança et s’intensifiait en chaleur, l’eau manquait, les villes les plus humbles se dépeuplaient au"},{"type":"p","text":"profit des très grandes villes, les ressources se faisaient bloquer par les mercenaires…"},{"type":"p","text":"Lui qui n’avait jamais eu de valeur morale, de foi ou d’ambition, pas même de considération pour le"},{"type":"p","text":"genre humain, se sentit pourtant d’agir, commençant à stocker des vivres, des munitions, planquer"},{"type":"p","text":"des soldats mexicains, servir de soutien aux troupes des cartels face à l’envahisseur."},{"type":"p","text":"Après la guerre et face à ce qui restait de sa région, il décida de se planquer, il s’installa dans son"},{"type":"p","text":"« Bunkfarm », un « bunker-ferme » comme bien des survivalistes de 2035 et se lança dans une"},{"type":"p","text":"source de résilience entre lui et la société décadente."},{"type":"p","text":"A la tête d’une communauté de quelques deux cents « Enders », dont une dizaine dans son bunker, il"},{"type":"p","text":"mène le combat contre es hordes de motards et les corporatistes essayant de s’implanter."},{"type":"p","text":"Comme bien des crawlers de sa catégorie, il n’a ni logifate ni augmentations, il préfère utiliser des"},{"type":"p","text":"chiens, des jumelles optiques, faire son propre carburant, son propre alcool et élever des chèvres"},{"type":"p","text":"autour du bunker."},{"type":"p","text":"Farouche comme personne, s’il est excessivement connu comme « Enders », mieux vaut ne pas"},{"type":"p","text":"tenter de le trouver dans son désert, au sud de la Californie, il tire à vue sur toute personne qu’il ne"},{"type":"p","text":"connait pas et n’hésites pas à lâcher ses meutes de chiens semi-sauvages sur ceux qui résisteraient à"},{"type":"p","text":"ses tirs de sniper."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-gerrika-reese","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Gerrika REESE","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks","Enders"],"pnj":{"completeness":"detailed","real_name":"Gerrika REESE","identity_keys":["Gerrika REESE","Lady Desert"],"statut":"Enders","organisation":"Neopunks","age":"30 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Gerrika REESE"],["Alias / désignation","Lady Desert"],["Âge","30 ans"],["Affiliations","Enders"],["Nationalité d’origine","Américaine"],["Famille Crawler","Neopunks"],["Sous-type","Enders"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Gerrika est née en 2005, à San Francisco."},{"type":"p","text":"Cette infirmière de métier a vécu normalement jusqu’au Big One qui ravagea toute la Californie et"},{"type":"p","text":"plus particulièrement encore San Francisco, on l’attendait plutôt à Los Angeles, mais quand il survint,"},{"type":"p","text":"il fut saisissant tant il fut démentiel."},{"type":"p","text":"Des millions de morts et de bâtiments en ruines en quelques heures et ce n’était que le début, toutes"},{"type":"p","text":"les villes côtières furent ravagées par des tsunamis, l’eau s’infiltra partout dans les ruines laissées par"},{"type":"p","text":"les premiers séismes, en effet, si on parle « Du » Big One, ce qui fut le plus catastrophique fut la suite"},{"type":"p","text":"continue de séisme de moindre ampleur qui continua pendant une semaine entière, moindre"},{"type":"p","text":"ampleur en comparaison seulement du plus ravageur."},{"type":"p","text":"Quand la terre se calma, que l’eau commença à stagner, ce furent les maladies et la faim qui"},{"type":"p","text":"frappèrent, les moustiques transportèrent des maladies méconnues ou négligées du moins, les"},{"type":"p","text":"populations furent affectées durablement à une époque où la guerre faisait encore rage et où les"},{"type":"p","text":"autorités étaient focalisées dessus, mobilisant policiers, pompiers et secouristes sur le front, les"},{"type":"p","text":"services dans le reste du pays étaient en standby, une grave erreur qui eut un coût en vies humaines."},{"type":"p","text":"Gerrika fit ce qu’elle pouvait, quand les sols commencèrent à sécher, hélas, de nouveaux problèmes"},{"type":"p","text":"furent constatés, l’ouverture d’immenses dolines en pleine ville de San Francisco commença à"},{"type":"p","text":"engloutir les bâtiments qui avaient résisté. Elle quitta sa ville natale en 2029, n’en pouvant plus."},{"type":"p","text":"Traumatisée, elle s’installa à l’écart, dans des collines du Nevada. Le bond technologique lui fit"},{"type":"p","text":"horreur, comment des villes entières pouvaient investir autant dans des systèmes destinés à bourrer"},{"type":"p","text":"les cranes de publicité et ne pas préserver ses citoyens des catastrophes naturelles ?"},{"type":"p","text":"Elle ne chercha pas à y résister mais s’en éloigner, joignant une communauté de 800 survivalistes qui,"},{"type":"p","text":"comme elle, avaient décidé de s’éloigner de la prochaine grande catastrophe, Los Angeles n’étant en"},{"type":"p","text":"rien préservée d’un second Big one…"},{"type":"p","text":"Calme et compatissante de nature, elle est néanmoins très méfiante Gerrika ne se trompe jamais sur"},{"type":"p","text":"la nature des gens, et ne laisse pas entrer n’importe qui dans sa communauté, elle est extrêmement"},{"type":"p","text":"hostile aux gundrivers en revanches, bien qu’elle ne traite souvent avec eux."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-daft-vador-kaine-reid","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"« Daft Vador » / Kaine REID","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","DeathRunners","Voidrunners"],"pnj":{"completeness":"detailed","real_name":"« Daft Vador » / Kaine REID","identity_keys":["« Daft Vador » / Kaine REID","l’ombre sans visage"],"statut":"Voidrunners","organisation":"DeathRunners","age":"??ans","nationalite":"américaine ?"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","« Daft Vador » / Kaine REID"],["Alias / désignation","l’ombre sans visage"],["Âge","??ans"],["Affiliations","Voidrunners"],["Nationalité d’origine","américaine ?"],["Famille Crawler","DeathRunners"],["Sous-type","Voidrunners"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"ancien militaire américain étant donné qu’il porte des plaques d’identifications, qu’il est formé au"},{"type":"p","text":"combat au corps à corps comme en tir."},{"type":"p","text":"Sniper difficile à égaler, il est équipé des meilleurs armes et manteaux de camouflage optique des"},{"type":"p","text":"différentes corporations."},{"type":"p","text":"De tous les assassins, c’est le voidrunner qui incarne le mieux la définition de ce genre de"},{"type":"p","text":"mercenaires."},{"type":"p","text":"On a déjà vu une équipe du HWAB essayer de l’arrêter, quatre véhicules blinder lui barrer la route,"},{"type":"p","text":"18 hommes en armure d’intervention le tenir en joug et il est encore là, à abattre ses contrats, ayant"},{"type":"p","text":"fait cramer tous les systèmes des véhicules avant de tirer dans la tête de chaque policier avec une"},{"type":"p","text":"arme capable de perforer leur casque d’intervention et avant qu’un seul ne le vise."},{"type":"p","text":"Chouchou de la « Blanchisserie », jusqu’à l’apparition du « massacreur des égouts » aucun assassin"},{"type":"p","text":"non mafieux ne semblait l’égaler."},{"type":"p","text":"Si on sait presque aucune information sur la personne derrière le masque, on sait néanmoins que"},{"type":"p","text":"l’assassin est très réactif, excessivement furtif, il est réputé indétectable et très dangereux si on"},{"type":"p","text":"parvient à l’identifier, il n’hésite absolument pas à tuer toute personne croisant sa route et pouvant"},{"type":"p","text":"attester de sa présence."},{"type":"p","text":"Son arsenal est très variable et il utilise des armes de guerre aussi rares que coûteuses. Il est"},{"type":"p","text":"impossible d’en être certain mais étant attaqué par les armacorpos, il est probablement un voleur"},{"type":"p","text":"qui pille les usines ou les convois pour se fournir."},{"type":"p","text":"Malgré son pseudonyme assez geek, ce crawler n’est absolument pas un plaisantin, c’est un assassin"},{"type":"p","text":"qui a une liste plus que longue de contrats qu’il a réussi à achever et souvent dans des conditions"},{"type":"p","text":"difficiles."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[{"type":"p","text":"On ignore qui est « Daft Vador », s’il s’agit d’un homme ou d’une femme, on suppose que c’est un"},{"type":"p","text":"On sait qu’il travaille en équipe mais on ignore combien sont derrière ce masque."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-dan-shelong","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Dan SHELONG","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neurodivers","Neurokillers"],"pnj":{"completeness":"detailed","real_name":"Dan SHELONG","identity_keys":["Dan SHELONG","la pluie écarlate"],"statut":"Neurokillers","organisation":"Neurodivers","age":"25 ans","nationalite":"américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Dan SHELONG"],["Alias / désignation","la pluie écarlate"],["Âge","25 ans"],["Affiliations","Neurokillers"],["Nationalité d’origine","américaine"],["Famille Crawler","Neurodivers"],["Sous-type","Neurokillers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Né en 2010, à Tucson, de parents descendants de chinois, Dan a toujours été un geek adorateur de"},{"type":"p","text":"jeux-vidéo, d’informatique et de nouvelles technologies"},{"type":"p","text":"Quand, à 14 ans, en 2024, il vit son père être envoyé par la conscription, il ne réalisa pas que c’était"},{"type":"p","text":"la dernière fois qu’il le verrait. Il en veut d’ailleurs encore de nos jours au gouvernement pour avoir"},{"type":"p","text":"autant sacrifier en vain des soldats."},{"type":"p","text":"Le jeune asiatique a vécu les grandes crises et catastrophes avec stupéfaction, tombant en même"},{"type":"p","text":"temps que la perte de son père, en 2026, ce fut son frère ainé qui fut appelé sous les drapeaux mais"},{"type":"p","text":"qui préféra déserter."},{"type":"p","text":"Il avait 20 ans en 2030 lors du bond technologique et fut grandement influencé par tous les"},{"type":"p","text":"changements qu’ils amenèrent."},{"type":"p","text":"Anti-gouvernemental depuis la mort de son père et l’emprisonnement de son frère, son logifate"},{"type":"p","text":"s’avéra si mauvais qu’aucune université n’accepta son excellent dossier. C’est à ce moment que sa"},{"type":"p","text":"colère contre la société éclata vraiment. Au lieu de joindre les insurgés néanmoins, il resta un"},{"type":"p","text":"crawler parmi les autres, un neurodiver mais il se spécialisa dans l’assassinat et le neurohack."},{"type":"p","text":"Entrant dans les augmentations neurales des gens, il devint un des plus grands experts de la guerre"},{"type":"p","text":"psychologique, notamment avec l’assassinat de Stephen BARNER, le vice-président de Bubble"},{"type":"p","text":"corporation. Yellowfood paya SHELONG pour faire que Barner ne pose plus soucis, l’assassin s’occupa"},{"type":"p","text":"de sa victime en la harcelant, submergeant son cerveau d’informations, il ne le rendit pas seulement"},{"type":"p","text":"dingue mais le fit se ruiner, ruiner sa corporation, il le poussa à essayer de tuer ses enfants et c’est"},{"type":"p","text":"finalement son épouse qui le tua en les défendant."},{"type":"p","text":"Il réitéra sa méthode pour dégager Ortena JACKSON, une sénatrice extrêmement virulente contre les"},{"type":"p","text":"corporations, elle était la sœur de Terry JACKSON, sénateur qui fut, entre autres, un partisan de la"},{"type":"p","text":"conscription durant la guerre. Ortena devint folle et agressa d’autres sénateurs, elle fut tuée alors"},{"type":"p","text":"que la forcenée tentait d’aller vers le bureau de la présidente-gouverneure."},{"type":"p","text":"Dan est réputé quelque peu psychopathe et sadique mais il est un excellent neurokiller de fait."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-mi-yeon-ryong","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Mi-Yeon RYONG","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Meditechs","Venomers"],"pnj":{"completeness":"detailed","real_name":"Mi-Yeon RYONG","identity_keys":["Mi-Yeon RYONG","Le monstre de Yungcheon"],"statut":"Venomers","organisation":"Meditechs","age":"45 ans","nationalite":"coréenne"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Mi-Yeon RYONG"],["Alias / désignation","Le monstre de Yungcheon"],["Âge","45 ans"],["Affiliations","Venomers"],["Nationalité d’origine","coréenne"],["Famille Crawler","Meditechs"],["Sous-type","Venomers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["???"],["???"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Il est rare qu’un monstre ne se montre avec un visage d’ange et des airs aussi gracieux que Mi-Yeon."},{"type":"p","text":"Issue de la très grande famille riche des RYONG, elle était dans les médecins de l’armée nord￾coréenne et on lui doit énormément de travaux sur les augmentations coréennes."},{"type":"p","text":"Si elle n’est pas la Leslie Wright de l’ennemi, elle reste un des plus gros cerveaux maléfiques de ce"},{"type":"p","text":"conflit bien qu’elle y prit part sur sa seconde moitié quand les Américains et leurs alliés"},{"type":"p","text":"commencèrent à répondre et prendre l’avantage."},{"type":"p","text":"Eternellement figée avec un visage de 25 ans, elle s’est faite rapatriée avec des civiles mais est"},{"type":"p","text":"toujours activement recherchée dans le monde entier pour ses expériences et avoir participé au"},{"type":"p","text":"régime abject des Nord-coréens."},{"type":"p","text":"Au début, elle était protégée par différentes megacorporations, telle que Biosun avait d’être"},{"type":"p","text":"totalement abandonnée une fois ses savoirs épuisés. Incapable de vivre dans la « société"},{"type":"p","text":"gouvernementale », elle est contrainte aux ombres des zones abandonnées, le CBII la traquant"},{"type":"p","text":"toujours."},{"type":"p","text":"Les restes de l’armée coréennes du nord ont des cellules terroristes en Californie, elle est celle qui les"},{"type":"p","text":"équipe d’augmentations et les soigne, elle participe aussi aux soins de l’insurrection civile, ayant tout"},{"type":"p","text":"à gagner à être protégées par les « frelons »."},{"type":"p","text":"Fondamentalement, Mi-Yeon reste peu politisée, elle ne prend part que par intérêt personnel et"},{"type":"p","text":"profit et se fichait assez de l’idéologie qu’elle servait, gorgée d’orgueil, elle se voit comme la véritable"},{"type":"p","text":"« mère » de l’ère technologique qu’on attribue à Leslie Wright et ses équipes. Pendant un temps, elle"},{"type":"p","text":"avait pour projet d’assassiner le plus « grand génie du millénaire », avant de se raviser."},{"type":"p","text":"Les « cliniques noires » qu’elle possèdent sont aussi éphémères qu’efficaces et son extrêmement"},{"type":"p","text":"ciblées par le LAUS quand il cherche à limiter l’activité des insurgés."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-yong-gi-mangjol","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Yong-Gi MANGJOL","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Gundrivers","Mandealers"],"pnj":{"completeness":"detailed","real_name":"Yong-Gi MANGJOL","identity_keys":["Yong-Gi MANGJOL","Le traitre de l’Asie"],"statut":"Mandealers","organisation":"Gundrivers","age":"24 ans","nationalite":"coréenne"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Yong-Gi MANGJOL"],["Alias / désignation","Le traitre de l’Asie"],["Âge","24 ans"],["Affiliations","Mandealers"],["Nationalité d’origine","coréenne"],["Famille Crawler","Gundrivers"],["Sous-type","Mandealers"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["?"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Yong-gi est né en 2011, à Seoul."},{"type":"p","text":"Âgé de seulement 11 ans en 2022, il a été envoyé aux Etats-Unis assez vite après l’invasion de la"},{"type":"p","text":"Corée du nord sur celle du sud."},{"type":"p","text":"Ce petit était déjà très intelligent, mais il se montra encore plus malin une fois débarqué en"},{"type":"p","text":"Californie."},{"type":"p","text":"Débrouillard au possible, le gosse était de tous les coups, intégrant vite quelques petits gangs de"},{"type":"p","text":"gamins, il avait du mal à saisir pourquoi les petits afro, les petit hispaniques et les blancs se"},{"type":"p","text":"mélangeaient si peu alors qu’en classe ils étaient tous ensembles."},{"type":"p","text":"Au début totalement méprisé par son origine coréenne, les gosses ne faisant pas la distinction entre"},{"type":"p","text":"nord-coréens et sud-coréens, il se fit doucement une place en se faisant appeler « Jon Manker » pour"},{"type":"p","text":"faire plus américain."},{"type":"p","text":"La petite frappe qu’il devint trainait dans tous les quartiers, dealant, colportant des informations, très"},{"type":"p","text":"vite il devint un indic de la police et dès ses 17 ans, en 2028 les policiers se référaient à lui pour savoir"},{"type":"p","text":"ce que faisaient les gangs japonais, coréens ou chinois, en effet, Yong avait un rejet assez fort des"},{"type":"p","text":"populations asiatiques, particulièrement des coréens, les balançant aisément en espionnant pour les"},{"type":"p","text":"gangs rivaux ou la police."},{"type":"p","text":"Les crawlers apparurent avec le logifate, mais Yong ne changeant pas vraiment de vie en se voyant"},{"type":"p","text":"recalé à des petits boulots, ça ne lui faisait rien."},{"type":"p","text":"En 2033 il commença à prendre de l’ampleur, à 22 ans, fournissant aux fixers des noms des planques"},{"type":"p","text":"et des infos sur des coréens immigrés illégalement ou bien d’anciens soldats ennemis de l’Alliance"},{"type":"p","text":"pacifique."},{"type":"p","text":"« Mandealers », lui et son groupe s’occupait d’offrir à ses compatriotes des planques et du fric pour"},{"type":"p","text":"mieux les vendre derrière."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-crawlers-docx-ogshaata-otto","dataset":"realite-v9-crawlers-pnj","category":"Personnages","sourceCategory":"Réalité","title":"Ogshaata « Otto »","source":"TUC_organisations_crawlers_V2(3).docx","status":"canon_source","rebuildV2":true,"tags":["Réalité","PNJ","Crawlers","Crawlers V2","Neopunks","Enders"],"pnj":{"completeness":"detailed","real_name":"Ogshaata « Otto »","identity_keys":["Ogshaata « Otto »","Le chaman"],"statut":"Enders","organisation":"Neopunks","age":"59 ans","nationalite":"Américaine"},"sections":[{"id":"crawlers-v2-fiche","title":"Profil Crawler","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom","Ogshaata « Otto »"],["Alias / désignation","Le chaman"],["Âge","59 ans"],["Affiliations","Enders"],["Nationalité d’origine","Américaine"],["Famille Crawler","Neopunks"],["Sous-type","Enders"]]}]},{"id":"crawlers-v2-relations","title":"Relations connues · Crawlers","level":2,"blocks":[{"type":"table","rows":[["Relation"],["Koshaway the Grey"],["?"]]}]},{"id":"crawlers-v2-realite","title":"Informations Réalité · Crawlers","level":2,"blocks":[{"type":"p","text":"Ogshaata est né en 1976, dans la réserve de Colorado River. Il se fait surnommer « Otto » par les"},{"type":"p","text":"blancs ayant du mal avec les noms américains."},{"type":"p","text":"Jeune cheyenne, il quitta la communauté quand son frère fut retrouvé dévoré par un coyote."},{"type":"p","text":"Refusant les résultats de l’enquête de police, il était convaincu que c’était un loup et décida de le"},{"type":"p","text":"chasser."},{"type":"p","text":"Il revint des années plus tard, sans rien avoir réussi et fut pris sous son aile par un chaman."},{"type":"p","text":"Il quitta à nouveau la réserve quand des casinos supplémentaires s’installèrent, méprisant les jeunes"},{"type":"p","text":"qui s’enthousiasmèrent d’y travailler."},{"type":"p","text":"Malgré la création de la grande réserve, ; Ogshaata est assez peu ouvert au concept même de"},{"type":"p","text":"réserve, tout le continent appartient aux amérindiens selon lui et il installa donc des petites maisons"},{"type":"p","text":"où bon lui semble sans rien demander à personne, afin d’y stocker vivre, munitions et autres"},{"type":"p","text":"ressources nécessaires à ses errances dans le pays."},{"type":"p","text":"Se baladant dans un smoking blanc rayé toujours impeccable, Ogshaata évite scrupuleusement les"},{"type":"p","text":"grandes villes, et entre toutes, il a une haine profonde pour Los Angeles et las Vegas qui seraient des"},{"type":"p","text":"concentrations « de mauvais esprits » selon ses dires."},{"type":"p","text":"Il évoque souvent Koshaway, un Indien du siècle précédant comme s’ils étaient amis, preuve d’un"},{"type":"p","text":"début de démence probable chez le chaman sur qui la solitude le pèse souvent puisqu’on le voit"},{"type":"p","text":"parler seul dès qu’on lui tourne le dos."},{"type":"p","text":"Malgré sa folie, c’est un redoutable combattant et un tireur efficace, entre ses bagues sur ses gants"},{"type":"p","text":"de cuir et la tête de hache sur la crosse de son fusil, il sait parfaitement alterner entre tir, mêlée et"},{"type":"p","text":"combat à mains nus dans la même seconde, étant un excellent combattant maitrisant l’Okichitaw."},{"type":"p","text":"En tant que Enders, il ne se fait aucune illusion, la Terre n’en est qu’à ses débuts pour corriger"},{"type":"p","text":"l’Humanité, et ceux qui s’engouffrent dans le maelström technologique ne s’en sortiront pas quand"},{"type":"p","text":"elle durcira le ton."}]},{"id":"crawlers-v2-mj","title":"Dossier MJ · Crawlers","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
